<template>
  <div class="ui basic segment t-print">
    <h3 class="ui dividing header">
      Transaction #{{trx.id}}
      <div :class="trx.status == 'approved' ? 'teal ' : 'red'"
            class="ui horizontal label">
        {{trx.status | capitalize}}
      </div>
      <div class="sub header">Date: <strong>{{trx.created_at | displayDate}}</strong></div>
    </h3>

    <ul>
      <li>Transaction ID: {{trx.id}}</li>
      <li>
        Amount:
        <span :class="trx.type == 'debit' ? 'red' : 'green'">
          {{trx.type == 'debit' ? '-' : '+'}}
          {{(trx.amount / 100) | currency ''}} {{trx.currency}}
        </span>
      </li>
      <li>Type: {{state.transaction_types[trx.transaction_type]}} / {{trx.type | capitalize}}</li>
      <li>Description: {{trx.description}}</li>
      <li v-if="trx.note">Note: {{trx.note}}</li>
      <li v-if="showBalance">Balance: {{(trx.balance / 100) | currency ''}} {{trx.currency}}</li>
      <li v-if="trx.systan">Systan: {{trx.systan}}</li>
      <li v-if="trx.reference_number">Reference number: {{trx.reference_number}}</li>
      <li>Status: {{trx.status | capitalize}}</li>
      <li>Date: {{trx.created_at | displayDate}}</li>
    </ul>

    <a class="ui basic button" @click.prevent="print()">
      <i class="print icon"></i>Print
    </a>
    <a class="ui basic button" @click="utils.cancelAction(state, false)">
      Close
    </a>

  </div>
</template>

<script>

import store from '../../store'

export default {
  name: 'transaction-details',

  data () {
    return {
      state: store.state,
      utils: store.utils
    }
  },

  props: ['trx'],

  created: function () {
    this.showBalance = Object.keys(this.state.constants.trx_transaction_types.mpos.types).indexOf(this.trx.transaction_type) === -1
  },

  methods: {
    print () {
      $('.t-print').printThis()
    }
  }

}
</script>
