/**
 * HTML Sanitization Utility
 *
 * Uses DOMPurify to sanitize HTML content and prevent XSS attacks.
 * This is critical for rendering user-generated or CMS content safely.
 *
 * TASK 3: XSS Vulnerability Fix
 */

import DOMPurify from 'dompurify'

/**
 * Sanitize HTML content to prevent XSS attacks
 *
 * @param {string} dirty - Potentially unsafe HTML string
 * @param {object} config - Optional DOMPurify configuration
 * @returns {string} - Sanitized HTML safe for rendering
 *
 * @example
 * const safeHTML = sanitizeHTML(userInput)
 * // Use in template: {{{ safeHTML }}}
 */
export function sanitizeHTML (dirty, config = {}) {
  if (!dirty || typeof dirty !== 'string') {
    return ''
  }

  // Default configuration - allow common formatting tags
  const defaultConfig = {
    ALLOWED_TAGS: [
      // Text formatting
      'b', 'i', 'em', 'strong', 'u', 's', 'strike', 'del', 'ins', 'mark',
      'small', 'sub', 'sup', 'code', 'pre', 'blockquote',

      // Lists
      'ul', 'ol', 'li',

      // Headings
      'h1', 'h2', 'h3', 'h4', 'h5', 'h6',

      // Paragraphs and line breaks
      'p', 'br', 'hr', 'div', 'span',

      // Tables
      'table', 'thead', 'tbody', 'tfoot', 'tr', 'th', 'td',

      // Links (with restrictions)
      'a'
    ],

    ALLOWED_ATTR: [
      // Allow class for styling
      'class',
      // Allow href only for links
      'href',
      // Allow title for accessibility
      'title'
    ],

    // Protocol whitelist for links (prevent javascript: urls)
    ALLOWED_URI_REGEXP: /^(?:(?:(?:f|ht)tps?|mailto|tel|callto|cid|xmpp):|[^a-z]|[a-z+.\-]+(?:[^a-z+.\-:]|$))/i,

    // Keep HTML structure
    KEEP_CONTENT: true,

    // Return sanitized string (not DOM)
    RETURN_DOM: false,
    RETURN_DOM_FRAGMENT: false,

    // Security settings
    SAFE_FOR_TEMPLATES: true,
    WHOLE_DOCUMENT: false,
    FORCE_BODY: false
  }

  // Merge user config with defaults
  const finalConfig = { ...defaultConfig, ...config }

  // Sanitize and return
  return DOMPurify.sanitize(dirty, finalConfig)
}

/**
 * Strict sanitization - text only, no HTML
 *
 * @param {string} dirty - Potentially unsafe string
 * @returns {string} - Plain text with all HTML removed
 *
 * @example
 * const plainText = sanitizeText(userInput)
 */
export function sanitizeText (dirty) {
  if (!dirty || typeof dirty !== 'string') {
    return ''
  }

  return DOMPurify.sanitize(dirty, {
    ALLOWED_TAGS: [],
    ALLOWED_ATTR: [],
    KEEP_CONTENT: true
  })
}

/**
 * Sanitize HTML for CMS/Admin content
 * More permissive than default, but still safe
 *
 * @param {string} dirty - CMS HTML content
 * @returns {string} - Sanitized HTML
 */
export function sanitizeCMSContent (dirty) {
  return sanitizeHTML(dirty, {
    // Add more tags for rich CMS content
    ADD_TAGS: ['iframe'],
    ADD_ATTR: ['target', 'rel', 'style'],

    // Stricter URL validation for iframes
    ALLOWED_URI_REGEXP: /^(?:(?:(?:f|ht)tps?|mailto|tel):|[^a-z]|[a-z+.\-]+(?:[^a-z+.\-:]|$))/i
  })
}

export default {
  sanitizeHTML,
  sanitizeText,
  sanitizeCMSContent
}
