<template>
  <div>

    <h3 class="ui dividing header">
      {{title}}
    </h3>

    <div v-if="false">
      <template v-for="(change, changeIndex) in changes">
        <template v-for="(item, key) in change">
          <div :key="`${changeIndex}-${key}`" class="ui secondary segment" v-if="key == 'created_at'">
            {{item | displayDate}}
          </div>
          <div :key="`${changeIndex}-${key}`" class="ui segment" v-if="key == 'diff'">
            <div class="ui horizontal middle aligned divided list">
              <div class="item" v-for="(attr, attrKey) in item" :key="attrKey">
                <span class="ui small label">{{attrKey | humanize}}</span> <span class="ui item">{{attr[0]}}</span> => {{attr[1]}}
              </div>
            </div>
          </div>
        </template>
      </template>
    </div>


    <table class="ui very basic compact table">
      <thead class="pointer">
        <tr>
          <th>Time</th>
          <th>Change</th>
        </tr>
      </thead>

      <tbody v-if="changes.length == 0">
        <tr>
          <td colspan="2">
            No records.
          </td>
        </tr>
      </tbody>

      <tbody v-else>
        <template v-for="(change, index) in changes">
          <tr :key="change.created_at">
            <td>
              {{change.created_at | displayDate}}
            </td>
            <td>
              <div v-for="(attr, key) in change.diff" :key="key" style="padding-top: 2px;">
                <span class="ui small label">{{key | humanize}}</span> <span class="ui item">{{attr[0]}}</span> => {{attr[1]}}
              </div>
            </td>
          </tr>
        </template>
      </tbody>
    </table>


    <a class="ui basic button" @click="utils.cancelAction(state)">Close</a>

  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'

export default {

  data () {
    return {
      changes: '',
      utils: store.utils,
      state: store.state
    }
  },

  props: ['title', 'path'],

  created: function () {
    this.getChanges()
  },

  methods: {

    getChanges () {
      if (this.changes) { return }
      this.$api.get(url_for(this.path)).then(
        (response) => {
          this.changes = response.data
        },
        (response) => {console.log(response.data)}
      )
    }
  }
}
</script>