<template>
  <div>

    <form v-show="message" class="ui reply form">

      <div class="field" :class="{ error: errors.title }">
        <input  placeholder="Enter subject"
                type="text"
                v-model="reply.title"><br>
        <div v-if="errors.title" class="ui basic red pointing prompt label transition visible">{{errors.title[0]}}</div>
      </div>

      <div class="field" :class="{ error: errors.body }">
        <textarea v-model="reply.body" placeholder="Enter message text"></textarea><br>
        <div v-if="errors.body" class="ui basic red pointing prompt label transition visible">{{errors.body[0]}}</div>
      </div>

      <a @click="sendReply()" :class="{disabled: state.processing}"
              class="ui blue button">
        Send reply
      </a>

      <a class="ui basic button" @click="utils.cancelAction(state)">
        Close
      </a>
    </form>

  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'

export default {
  name: 'reply',

  data () {
    return {
      state: store.state,
      utils: store.utils,
      reply: {},
      errors: false
    }
  },

  props: ['message'],

  watch: {
    message: {
      immediate: true,
      handler(newMessage) {
        if (newMessage && newMessage.title) {
          this.reply.title = 'Re: ' + newMessage.title
        }
      }
    }
  },

  methods: {
    sendReply () {
      this.$api.post(url_for('messages', this.message.id, 'reply'), this.reply).then(
        (response) => {
          this.state.message = { header: 'Success', class: 'success', list: ['Message sent.'] }
          this.$parent.$parent.getMessages()
          this.utils.cancelAction(this.state)
        },
        (response) => {this.errors = response.data}
      )
    }
  }
}
</script>
