<template>
  <div>

    <form class="ui form" autocomplete="false">

      <h3 class="ui dividing header">
        <div class="content">
          Terminal #{{cashier.terminal_id}}: Update {{cashier.full_name}}
        </div>
      </h3>

      <div class="inline field" :class="{ error: errors.manager }">
        <div class="ui checkbox">
          <input  type="checkbox"
                  v-model="cashier.manager"
                  v-bind:true-value="true"
                  v-bind:false-value="false">
          <label>Manager</label>
        </div>
        <div v-if="errors.manager" class="ui basic red pointing prompt label transition visible">{{errors.manager[0]}}</div>
      </div>

      <div class="inline field" :class="{ error: errors.active }">
        <div class="ui checkbox">
          <input  type="checkbox"
                  v-model="cashier.active"
                  v-bind:true-value="true"
                  v-bind:false-value="false">
          <label>Active</label>
        </div>
        <div v-if="errors.active" class="ui basic red pointing prompt label transition visible">{{errors.active[0]}}</div>
      </div>

      <div v-if="!state.show_otp">
        <button class="ui blue submit button"
                :class="{disabled: state.processing}"
                @click.prevent="updateCashier()">
          Edit cashier
        </button>

        <a class="ui basic button" @click="cashier = utils.cancelAction(state)">
          Cancel
        </a>
      </div>

    </form>

    <div v-if="state.show_otp">
      <br>
      <verify-otp></verify-otp>
    </div>

  </div>

</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'
import VerifyOtp from '../verify_otp.vue'
import _ from 'underscore'

export default {
  name: 'update-cashier',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      errors: ''
    }
  },

  props: ['terminal', 'cashier'],

  components: {
    'verify-otp': VerifyOtp
  },

  mounted: function () {
    $('.ui.checkbox').checkbox()
  },

  methods: {
    updateCashier () {
      var payload = _.pick(this.cashier, ['active', 'manager'])
      this.$api.post(url_for('terminals', this.state.sub_id, 'cashiers', this.state.sub_sub_id), payload).then(
        (response) => {
          this.state.message = { header: 'Success', class: 'success', list: ['Cashier updated.'] }
          this.utils.cancelAction(this.state)
          this.utils.scrollToTop()
        },
        (response) => {this.errors = response.data}
      )
    }
  }

}
</script>