import {url_for, session_timeout, session_extension_timeout} from '../constants'
import {router} from '../index'
import {upgrade_client} from './upgrade_client'
import store from '../store'
import { formatErrorForMessage } from '../utils/errorHandler'

var state = store.state

export default {

  // login
  login (context, creds, msg) {
    context.$api.post(url_for('login'), creds).then(
      (response) => {
        this.storeLoginResponse(context, response.data)

        // reload html if js file changed
        upgrade_client(response.data.spa_file_name)

        if (msg) {
          state.message = msg
        } else {
          state.message = { header: 'Please authenticate yourself', class: 'success', list: ['Enter the code from your authenticator.'] }
        }
        state.notification = false

        // disable tfa check on login with this
        // state.authorized_login = true
        // router.push('/home')

        router.push('/authorize')
      },

      (response) => {
        // Use error handler for user-friendly messages
        state.message = formatErrorForMessage(response, 'login')
      }
    )
  },

  // signup new user
  signup (context, profile, redirect) {
    context.$api.post(url_for('signup'), profile).then(

      (response) => {
        state.message = { header: 'Registration succesfull', class: 'success', list: ['Check your email for next step.'] }
        router.push('/')
      },

      (response) => {
        context.errors = response.data
      }
    )
  },

  // logout
  logout (context) {

    // logout on server - it deletes otp session there
    context.$api.post(url_for('logout'), {}).then(
      (response) => {},
      (response) => {
        // Silently handle logout errors - user will be logged out client-side anyway
        if (process.env.NODE_ENV !== 'production') {
          console.warn('Logout error:', response.data)
        }
      }
    )

    // logout on client
    this.cleanup()
    state.message = { header: 'Have a nice day', class: 'success', list: ['You are logged out.'] }
    router.push('/login')
  },

  storeLoginResponse (context, data) {
    // store global data
    state.token = data.token
    state.authenticated = true
    state.profile = data.user
    // Parse settings if present, otherwise use empty object
    state.profile.settings = (data.user && data.user.settings) ? JSON.parse(data.user.settings) : {}
    state.extended_session = false // this toggle extended session dialog

    // start session counter
    this.triggerExtendSessionCounter(context)
  },

  cleanup () {
    // delete global  data
    state.token = false
    state.authenticated = false
    state.authorized_login = false
    state.extended_session = false
    state.profile = false
    state.notification = false
    state.id = false
    state.action = false
    state.cancelSearch('transaction')
  },

  // time counter to re-authenticate
  triggerExtendSessionCounter () {
    setTimeout(() => {
      if (state.authenticated) {
        state.extended_session = true // this opens login box

        // force logout if not extended
        setTimeout(() => {
          if (state.extended_session) {
            this.logout(router.app)
            state.notification = { title: 'Your session has expired'}
          }
        }, session_extension_timeout)

      }
    }, session_timeout)
  }
}
