<template>
  <div class="ui segment">

    <h2 class="ui dividing header">
      Edit account
    </h2>

    <form class="ui form" autocomplete="false">

      <div class="two fields">
        <div class="field" :class="{ error: errors.title }">
          <label>Title</label>
          <input  placeholder="Enter account title"
                  type="text"
                  v-model="account.title"><br>
          <div v-if="errors.title" class="ui basic red pointing prompt label transition visible">{{errors.title[0]}}</div>
        </div>
      </div>

      <div v-if="!state.show_otp">
        <button class="ui blue submit button"
                :class="{disabled: state.processing}"
                @click.prevent="editAccount()">
          Edit Account
        </button>

        <a class="ui basic button" @click="account = utils.cancelAction(state)">
          Cancel
        </a>
      </div>

    </form>

    <div v-if="state.show_otp">
      <br>
      <verify-otp :callback="editAccount"></verify-otp>
    </div>
  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'
import VerifyOtp from '../verify_otp.vue'
import _ from 'underscore'

export default {
  name: 'update-account',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      errors: ''
    }
  },

  props: ['account'],

  components: {
    'verify-otp': VerifyOtp
  },

  mounted: function () {
    $('select.dropdown').dropdown()
  },

  methods: {

    editAccount () {
      var payload = _.pick(this.account, ['title'])
      this.$api.post(url_for('accounts', this.account.id, 'update'), payload).then(
        (response) => {
          this.state.message = { header: 'Success', class: 'success', list: ['Your account is updated.'] }
          this.utils.cancelAction(this.state)
        },
        (response) => {this.errors = response.data}
      )
    }
  }

}
</script>
