<template>
  <div>

    <h2 class="ui dividing header">
      Voucher stock
      <a class="ui basic tiny blue button right floated" @click="add_notification = !add_notification"
         style="margin-top: -0.8em;">
        <i class="announcement icon"></i>
        Add/edit notification
      </a>
    </h2>

    <div v-show="add_notification" class="ui segment">

      <h4 class="ui dividing header">Add or edit notification</h4>

      <form class="ui form" autocomplete="false">
        <div class="two fields">
          <div class="field">
            <label>Voucher</label>
            <select v-model="voucher_name" class="ui dropdown" @change="setQuantity()">
              <option value="">Select voucher</option>
              <option v-for="v in sortedVoucherStocks" :key="v.name" :value="v['name']">{{v['name']}}</option>
            </select><br>
          </div>

          <div class="field">
            <label>Notification quantity</label>
            <input  placeholder="Enter notification quantity"
                    type="text"
                    v-model="quantity"><br>
          </div>
        </div>

        <p>
          <a class="ui blue submit button"
                  :class="{disabled: state.processing}"
                  @click="updateStocks()">
            Add/edit notification
          </a>

          <a class="ui basic button" @click="add_notification = !add_notification">
            Cancel
          </a>
        </p>

      </form>
    </div>

    <table class="ui very basic table right aligned">
      <thead>
        <tr class="pointer">
          <th class="left aligned">Product</th>
          <th>Quantity on stock</th>
          <th>Notification quantity</th>
          <th>Last replenish</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="stock in sortedVoucherStocks" :key="stock.name">
          <td class="left aligned">{{stock.name}}</td>
          <td>{{stock.quantity}}</td>
          <td>{{stocks[stock.name] || 'Not set'}}</td>
          <td>{{stock.updated_at | displayDate}}</td>
        </tr>
      </tbody>
    </table>

  </div>
</template>

<script>

import store from '../../../store'
import {url_for} from '../../../constants'

export default {

  data () {
    return {
      state: store.state,
      utils: store.utils,

      add_notification: false,
      voucher_name: '',
      quantity: ''
    }
  },

  props: ['account'],

  created: function () {
    this.stocks = this.account.settings.low_stock
  },

  mounted: function () {
    $('select.dropdown').dropdown()
  },

  computed: {
    sortedVoucherStocks() {
      if (!this.account || !this.account.voucher_stocks) return []
      return [...this.account.voucher_stocks].sort((a, b) => {
        return (a.name || '').localeCompare(b.name || '')
      })
    }
  },

  methods: {
    updateStocks () {
      this.stocks[this.voucher_name] = this.quantity

      this.$api.post(url_for('accounts', this.account.id, 'settings/update'), this.account.settings).then(
        (response) => {
          this.state.message = { header: 'Success', class: 'success', list: ['Notification is updated.'] }
          this.add_notification = false
        },
        (response) => {console.log(response.data)}
      )
    },

    setQuantity () {
      if (this.stocks[this.voucher_name]) {
        this.quantity = this.stocks[this.voucher_name]
      } else {
        this.quantity = ''
      }
    }
  }
}
</script>
