<template>
  <div>

    <div class="ui stackable grid reset-top a-print">

      <div class="five wide column reset-top">
        <balance :account="account"></balance>
      </div>

      <div class="eleven wide column reset-top">
        <h2 class="ui dividing header">
          <div class="content">
            <div class="account-title" :class="{pointer: accounts.length > 1}">
              {{account.title}}
              <a v-show="account && !account.active" class="ui horizontal orange label">Disabled</a>
              <a v-show="account && account.default" class="ui horizontal label reset-left-margin">Default</a>
              <i v-if="accounts.length > 1" class="angle down icon"></i>
            </div>

            <div class="ui popup pointing vertical menu transition hidden">
              <template v-for="(a, index) in accounts">
                <a :key="a.id" @click="getAccount(index)" class="item">
                  <h3 class="ui header">
                    {{a.title}}
                    <div v-show="!a.active" class="ui orange small horizontal label">Disabled</div>
                    <div v-show="a.default" class="ui small horizontal label">Default</div>
                  </h3>
                  <p>Account type: <strong>{{state.constants.account_types[a.type]}}</strong> |
                    Account number:<strong> #{{a.account_number}}</strong></p>
                </a>
              </template>
            </div>

            <div class="sub header">
              Account type: <strong>{{state.constants.account_types[account.type]}}</strong> |
              Account number: <strong>{{account.account_number}}</strong>
            </div>
          </div>
        </h2>

        <p>
          Client type: <strong>{{profile.type | capitalize}}</strong> |
          Logged as <strong>{{profile.first_name}} {{profile.last_name}}</strong>
        </p>

        <div class="ui small buttons">
          <template v-if="account.type == 'personal'">
            <a class="ui basic blue button" :class="{disabled: !account.active}" @click="utils.showAction(state, 'select-transfer', account)">
              <i class="reply icon"></i>
              Transfer funds
            </a>
            <a class="ui basic blue button" :class="{disabled: !account.active}" @click="utils.showAction(state, 'pay-bill', account)">
              <i class="building outline icon"></i>
              Pay a bill
            </a>
            <a class="ui basic blue button" :class="{disabled: !account.active}" @click="utils.showAction(state, 'buy-voucher', account)">
              <i class="barcode icon"></i>
              Buy a voucher
            </a>
          </template>

          <template v-if="account.type == 'business'">
            <a class="ui basic blue button" :class="{disabled: !account.active}" @click="utils.showAction(state, 'transfer', account)">
              <i class="reply icon"></i>
              Transfer funds
            </a>
            <a class="ui small basic blue button" @click="utils.showAction(state, 'profile', account)">
              <i class="info icon"></i>
              Merchant profile
            </a>
            <a class="ui small basic blue button" @click="utils.showAction(state, 'limits', account)">
              <i class="options icon"></i>
              Limits
            </a>
            <a class="ui small basic blue button" @click="utils.showAction(state, 'stocks', account)">
              <i class="barcode icon"></i>
              Voucher stock
            </a>
            <a class="ui small basic blue button" @click="utils.showAction(state, 'terminals', account)">
              <i class="calculator icon"></i>
              Terminals
            </a>
          </template>

          <template v-if="account.type == 'current' || account.type == 'savings'">
            <a  class="ui small basic blue button" :class="{disabled: !account.active}" @click="utils.showAction(state, 'transfer-bank', account)">
              <i class="reply icon"></i>
              Transfer funds
            </a>
            <a  class="ui small basic blue button" :class="{disabled: !account.active}" @click="utils.showAction(state, 'bank-balance-inquiry', account)">
              <i class="refresh icon"></i>
              Balance inquiry
            </a>
          </template>
        </div>

        <div class="ui small blue basic button dropdown top right">
          <div class="text">More</div>
          <i class="dropdown icon"></i>
          <div class="menu">
            <a class="item hide" @click="utils.showAction(state, 'changes', account)">
              <i class="history icon"></i>
              History
            </a>
            <a v-if="couldBeDefault(account)" class="item" @click="setAsDefault(account)">
              <i class="checkmark icon"></i>
              Set as default
            </a>
            <a class="item" @click="utils.showAction(state, 'edit', account)">
              <i class="edit icon"></i>
              Edit
            </a>
            <a class="item" @click.prevent="print(account)">
              <i class="print icon"></i>
              Print
            </a>
            <div class="divider"></div>
            <a class="item" @click="utils.comingSoon(state)">
              <i class="line chart icon"></i>
              Statistics
            </a>
          </div>
        </div>

      </div>
    </div>

    <div class="ui hidden divider medium"></div>

    <personal v-if="account.type == 'personal'" :account="account" :bank_accounts="bank_accounts" :callbacks="[getAccount]"></personal>
    <business v-if="account.type == 'business'" :account="account" :callbacks="[getAccount]"></business>
    <bank v-if="account.type == 'current' || account.type == 'savings'" :account="account" :callbacks="[getAccount]" :bank_accounts="bank_accounts"></bank>


    <update v-if="state.action == 'edit'" :account.sync="account"></update>
    <changes v-if="0 && state.action == 'changes'" title="History" :path="['accounts', account.id, 'changes'].join('/')"></changes>


    <services-lodgments v-if="show_lodgments && account.type == 'business'"
                        :account="account" :lodgments_switch.sync="show_lodgments"></services-lodgments>
    <transactions v-show="!show_lodgments" :lodgments_switch.sync="show_lodgments" :embedded="true"
                  ref="transactions" :account="account" :refresh_callbacks="[getAccount]"></transactions>

  </div>
</template>

<script>
import {url_for} from '../../constants'
import store from '../../store'

import Balance from './balance.vue'
import Personal from './personal/personal.vue'
import Business from './business/business.vue'
import Bank from './bank/bank.vue'

import Update from './update.vue'

import Transactions from '../transactions/transactions.vue'
import ServicesLodgments from '../lodgments/services_lodgments.vue'
// import Changes from '../shared/changes.vue'

import _ from 'underscore'

export default {

  name: 'account',

  data () {
    return {
      state: store.state,
      utils: store.utils,

      profile: store.state.profile,

      account: false,
      accounts: [],
      bank_accounts: [],

      show_lodgments: false,

      // search
      search: store.state.search.transaction
    }
  },

  components: {
    balance: Balance,
    personal: Personal,
    business: Business,
    bank: Bank,
    update: Update,
    transactions: Transactions,
    'services-lodgments': ServicesLodgments
    // changes: Changes
  },

  created: function () {
    this.getAccount()
  },

  mounted: function () {
  },

  methods: {
    getAccount (index) {

      // switch account
      if (_.isNumber(index)) {
        this.state.current_account_index = index
        $('.account-title').popup('hide')
        this.state.action = false // close any open component
        this.state.id = false
        this.show_lodgments = false
        this.utils.scrollToTop()
      }

      this.$api.get(url_for('accounts')).then(
        (response) => {
          this.accounts = response.data

          // Ensure current_account_index is valid
          if (!this.state.current_account_index || this.state.current_account_index >= this.accounts.length) {
            this.state.current_account_index = 0
          }

          this.account = this.accounts[this.state.current_account_index]

          if (this.account) {
            this.setExposureColor(this.account.exposure_amount, this.account.credit_limit) // set exposure color

            // get embedded transactions
            this.search.q = {account_id: this.account.id}
            if (this.$refs.transactions && this.$refs.transactions.getTransactions) {
              this.$refs.transactions.getTransactions()
            }
            this.$nextTick(() => {
              try {
                if ($ && $.fn && $.fn.dropdown) {
                  $('.ui.dropdown').dropdown({action: 'select'})
                }
              } catch (e) {
                // Semantic UI not loaded yet
              }
            })

            // add popup and hover for account selection for multiple accounts
            if (this.accounts.length > 1) {
              $('.account-title').popup({on: 'click', inline: true, position: 'bottom left', distanceAway: 0, lastResort: 'bottom left'})
            }

            // set bank accounts for transfers
            var this_account = this.account
            this.bank_accounts = this.utils._.filter(this.accounts, function (a) {
              return ((a.type === 'savings' || a.type === 'current') && a.id !== this_account.id)
            })
          }
        },
        (response) => {console.log(response.data)}
      )
    },

    couldBeDefault (account) {
      // ['personal', 'business']
      return !account.default && Object.keys(this.state.constants.wallet_account_types).find(function (type) { return account.type === type })
    },

    setAsDefault (account) {
      this.$api.post(url_for('accounts', this.account.id, 'set-default'), {}).then(
        (response) => {
          this.state.message = { header: 'Success', class: 'success', list: ['This account is now default account.'] }
          this.accounts.find(function (a) { return a.default }).default = false
          this.account.default = true
        },
        (response) => {console.log(response.data)}
      )
    },

    print () {
      $('.a-print').printThis()
    },

    setExposureColor (exposure, credit) {
      if (this.account.type !== 'business') { return }
      if (exposure < credit * 0.5) {
        this.exposure_color = 'green'
      } else if (exposure > credit * 0.75) {
        this.exposure_color = 'red'
      } else {
        this.exposure_color = 'orange'
      }
    }
  }

}
</script>
