export function upgrade_client (spa_file_name) {
  let $spaScript = $('script#spa-file')
  if ($spaScript.length === 0) return // Element doesn't exist in dev mode

  let current_spa_file_name = $spaScript.attr('src').split('/').slice(-1)[0]
  if (spa_file_name !== current_spa_file_name) {window.location.reload(true)}
}
