<template>
  <div class="for-print">

    <div class="ui stackable grid reset-top">
      <div class="twelve wide column reset-top">

        <h2 class="ui header">
          {{ page.title }}
          <div class="sub header">
            Last update: <strong>{{page.updated_at | displayDate}}</strong>
          </div>
        </h2>

      </div>

      <div class="four wide column reset-top">
        <div class="ui basic small button right floated" @click="print()">
          <i class="print icon"></i>Print
        </div>
      </div>
    </div>

    <br>
    <div v-html="sanitizedBody"></div>

  </div>
</template>

<script>

import store from '../../store'
import { sanitizeCMSContent } from '../../utils/sanitize'

export default {

  data () {
    return {
      pages: store.state.pages,
      page: ''
    }
  },

  computed: {
    sanitizedBody () {
      if (!this.page || !this.page.body) {
        return ''
      }
      // Sanitize CMS content to prevent XSS attacks
      // Allows formatting tags (bold, lists, links) but blocks malicious scripts
      return sanitizeCMSContent(this.page.body)
    }
  },

  props: ['slug'],

  created: function () {
    this.getPage(this.$route.slug || this.slug)
  },

  route: {
    canReuse: false
  },

  methods: {

    print () {
      $('.for-print').printThis()
    },

    getPage (slug) {
      this.page = this.pages[slug]
    }
  }
}
</script>
