<template>
  <div>

    <h2 class="ui header">
      <div class="content">
        Accounts
        <div class="sub header">Manage my accounts</div>
      </div>
    </h2>

    <table class="ui celled compact single line table">
      <thead>
        <tr>
          <th>Active</th>
          <th>Name</th>
          <th>IBAN</th>
          <th>Account number</th>
          <th class="right aligned">Balance</th>
          <th class="right aligned">Actions</th>
        </tr>
      </thead>

      <tbody>
        <template v-for="(account, index) in accounts">
          <tr :key="account.id" :class="{'disabled': state.id && state.id != account.id}">
            <td v-if="account.active" class="positive">
              <i class="icon checkmark"></i> Yes
            </td>
            <td v-else class="negative">
              <i class="icon remove"></i> No
            </td>
            <td>{{account.title}}</td>
            <td>{{account.iban}}</td>
            <td>{{account.account_number}}</td>
            <td class="right aligned">{{account.balance/100 | currency ''}} {{account.currency}}</td>
            <td class="right aligned">
              <div class="ui blue compact pointing dropdown top right small basic icon button">
                <i class="settings icon"></i>
                <div class="text">Actions</div>
                <div class="menu">

                  <a class="item" @click.prevent="utils.showAction(state, 'transfer', account)">
                    <i class="reply icon"></i>
                    Transfer
                  </a>

                  <a class="item" @click.prevent="utils.showAction(state, 'pay-bill', account)">
                    <i class="building icon"></i>
                    Pay a bill
                  </a>

                  <a class="item" @click.prevent="utils.showAction(state, 'buy-voucher', account)">
                    <i class="barcode icon"></i>
                    Buy a voucher
                  </a>

                  <div class="divider"></div>
                  <router-link to="transactions/1" active-class="active">
                    <i class="list icon"></i>
                    Transactions
                  </router-link>
                  <a class="item" @click.prevent="utils.showAction(state, 'terminals', account)">
                    <i class="calculator icon"></i>
                    Terminals
                  </a>
                  <div class="divider"></div>

                  <a class="item" @click.prevent="utils.showAction(state, 'edit', account)">
                    <i class="edit icon"></i>
                    Edit
                  </a>
                  <a class="item" @click.prevent="utils.showAction(state, 'changes', account)">
                    <i class="history icon"></i>
                    Changes
                  </a>
                  <div class="divider"></div>
                  <a class="item" @click.prevent="utils.comingSoon(state)">
                    <i class="line chart icon"></i>
                    Statistics
                  </a>
                </div>
              </div>

            </td>
          </tr>

          <tr v-if="state.id == account.id">
            <td colspan="8">

              <div class="ui basic segment" v-if="state.action == 'transfer'">
                <transfer :account="account" :callbacks="[getAccounts]"></transfer>
              </div>

              <div class="ui basic segment" v-if="state.action == 'pay-bill'">
                <pay-bill :account="account" :callbacks="[getAccounts]"></pay-bill>
              </div>

              <div class="ui basic segment" v-if="state.action == 'buy-voucher'">
                <buy-voucher :account="account" :callbacks="[getAccounts]"></buy-voucher>
              </div>

              <div class="ui basic basic segment" v-if="state.action == 'edit'">
                <update :account.sync="account"></update>
              </div>

              <div class="ui basic segment" v-if="state.action == 'terminals'">
                <terminals :account_id="account.id"></terminals>
              </div>

              <div class="ui basic segment" v-if="state.action == 'changes'">
                <changes title="Account changes" :path="['accounts', account.id, 'changes'].join('/')"></changes>
              </div>
            </td>
          </tr>
        </template>
      </tbody>
    </table>

    <button class="ui teal basic right floated small button hide">
      <i class="plus teal icon"></i>
      Add new account
    </button>

    <p class="hide">
      You can add and close account in different currencies at any time.
    </p>

    <div class="clearfix"></div>

  </div>
</template>

<script>
import {url_for} from '../../constants'
import store from '../../store'

import Changes from '../shared/changes.vue'
import Update from './update.vue'

import Terminals from '../terminals/terminals.vue'
import Transfer from './personal/transfer.vue'
import PayBill from './personal/pay_bill.vue'
import BuyVoucher from './personal/buy_voucher.vue'

export default {

  name: 'accounts',

  data () {
    return {
      accounts: false,
      state: store.state,
      utils: store.utils
    }
  },

  components: {
    changes: Changes,
    update: Update,
    terminals: Terminals,
    transfer: Transfer,
    'pay-bill': PayBill,
    'buy-voucher': BuyVoucher
  },

  created: function () {
    this.getAccounts()
  },

  methods: {
    getAccounts () {
      this.$api
        .get(url_for('accounts')).then(
          (response) => {
            this.accounts = response.data
            this.$nextTick(() => { // update dom
              try {
                if ($ && $.fn && $.fn.dropdown) {
                  $('.ui.dropdown').dropdown()
                }
              } catch (e) {
                // Semantic UI not loaded yet
              }
            })
          },
          (response) => {console.log(response.data)}
        )
    }
  }

}
</script>