<template>
  <div v-show="visible" transition="message" style="display: none; z-index: 999; position: fixed; top: 2em;  right: 1em;">
    <div :class="['ui', state.message.class, 'message']">
      <i class="close icon" @click="visible = false" style="padding-top: 3px;"></i>
      <div class="header" style="padding-right: .6em;">
        {{ state.message.header }}
      </div>
      <template v-if="state.message.list">
        <p v-if="state.message.list.length === 1">
          <strong>{{state.message.list[0]}}</strong>
        </p>
        <ul class="list" v-else>
          <li v-for="(item, index) in state.message.list" :key="index">{{ item }}</li>
        </ul>
      </template>
    </div>
  </div>
</template>

<script>
import store from '../store'

export default {
  name: 'message',

  data () {
    return {
      state: store.state,
      visible: false
    }
  },

  watch: {
    'state.message': function () {
      this.visible = true
      setTimeout(function () {
        this.visible = false
      }.bind(this), 5000)
    }
  }

}
</script>
