<template>
  <div class="ui segment">
    <h3 class="ui dividing header">
      Upload document
    </h3>

    <form class="ui form" autocomplete="false">

      <div class="field" :class="{ error: errors.type }">
        <label>Document type</label>
        <select v-model="document.type" class="ui dropdown">
          <option value="">Select document type</option>
          <option v-for="t in types" :value="$key" :key="index">{{t}}</option>
        </select><br>
        <div v-if="errors.type" class="ui basic red pointing prompt label transition visible">{{errors.type[0]}}</div>
      </div>

      <div class="field" :class="{ error: errors.image }">

        <label>Image</label>
        <div v-show="!document.image" class="ui fluid action input">
          <input type="file" @change="onFileChange">
          <input type="text" readonly placeholder="Select an image (max. 500kb)">
          <div class="ui icon button">
            <i class="file image outline icon"></i>
          </div>
        </div>

        <img v-if="document.image" class="ui medium image" :src="document.image">

        <div v-if="errors.image" class="ui basic red pointing prompt label transition visible">{{errors.image[0]}}</div>
      </div>

      <p>
        <button class="ui blue submit button"
                :class="{disabled: state.processing}"
                @click.prevent="documentUpload()">
          Upload
        </button>

        <button v-if="document.image" class="ui basic submit button" @click.prevent="replaceImage">Replace image</button>

        <a class="ui basic button" @click="account = utils.cancelAction(state)">
          Cancel
        </a>
      </p>

    </form>

  </div>

</template>

<script>

import {url_for, document_types} from '../../constants'
import store from '../../store'

export default {
  name: 'document',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      types: document_types,
      document: {image: ''},
      errors: {image: ''}
    }
  },

  props: ['callback'],

  mounted: function () {
    $('select.dropdown').dropdown()
    $('input:text, .ui.button', '.ui.action.input')
      .on('click', function (e) {
        $('input:file', $(e.target).parents()).click()
      })
  },

  methods: {

    documentUpload () {
      this.$api.post(url_for('profile/upload'), this.document).then(
        (response) => {
          this.callback()
          this.state.notification = {title: 'Document has been uploaded.', body: 'Once the documents are validated your account will be upgraded.'}
          this.utils.cancelAction(this.state)
        },
        (response) => {this.errors = response.data}
      )
    },

    onFileChange (e) {
      this.errors.image = ''
      var files = e.target.files || e.dataTransfer.files
      if (!files.length) {return}

      if (files[0].size > 500000) {
        this.errors.image = ['file is too large']
        return
      }

      var imageType = /image.*/
      if (files[0].type.match(imageType)) {
        this.createImage(files[0])
      } else {
        this.errors.image = ['file not supported']
      }
    },

    createImage (file) {
      var reader = new FileReader()

      reader.onload = (e) => {
        const dataURL = e.target.result
        // Security: Ensure the data URL is a valid image format
        // Prevents potential XSS if non-image files bypass MIME type check
        if (dataURL && dataURL.startsWith('data:image/')) {
          this.document.image = dataURL
        } else {
          this.errors.image = ['Invalid image format']
          this.document.image = ''
        }
      }
      reader.readAsDataURL(file)
    },

    replaceImage: function (e) {
      this.document.image = ''
      $('input:file', $(e.target).parents()).click()
    }

  }

}
</script>