<template>
  <div>
    <div class="ui basic segment">

      <form class="ui form" autocomplete="false">

        <h3 class="ui dividing header">Merchant profile</h3>

        <div class="two fields">
          <div class="field" :class="{ error: errors.merchant_name }">
            <label>Merchant name</label>
            <input  placeholder="Enter merchant name"
                    type="text"
                    v-model="terminal.merchant_name"><br>
            <div v-if="errors.merchant_name" class="ui basic red pointing prompt label transition visible">{{errors.merchant_name[0]}}</div>
          </div>

          <div class="field" :class="{ error: errors.merchant_address }">
            <label>Merchant address</label>
            <input  placeholder="Enter merchant address"
                    type="text"
                    v-model="terminal.merchant_address"><br>
            <div v-if="errors.merchant_address" class="ui basic red pointing prompt label transition visible">{{errors.merchant_address[0]}}</div>
          </div>
        </div>

        <div class="two fields">
          <div class="field" :class="{ error: errors.merchant_phone }">
            <label>Merchant phone</label>
            <input  placeholder="Enter merchant phone"
                    type="text"
                    v-model="terminal.merchant_phone"><br>
            <div v-if="errors.merchant_phone" class="ui basic red pointing prompt label transition visible">{{errors.merchant_phone[0]}}</div>
          </div>

          <div class="field" :class="{ error: errors.merchant_email }">
            <label>Merchant email</label>
            <input  placeholder="Enter merchant email"
                    type="text"
                    v-model="terminal.merchant_email"><br>
            <div v-if="errors.merchant_email" class="ui basic red pointing prompt label transition visible">{{errors.merchant_email[0]}}</div>
          </div>
        </div>

        <h3 class="ui dividing header">Terminal settings</h3>

        <div class="field" :class="{ error: errors.receipt_text }">
          <label>Receipt text</label>
          <textarea rows="4"
                    v-model="terminal.receipt_text"
                    placeholder="Enter 4 lines of text"></textarea><br>
          <div v-if="errors.receipt_text" class="ui basic red pointing prompt label transition visible">{{errors.receipt_text[0]}}</div>
        </div>

        <div v-if="!state.show_otp">
          <button class="ui blue submit button"
                  :class="{disabled: state.processing}"
                  @click.prevent="editTerminal()">
            Edit terminal
          </button>

          <a class="ui basic button" @click="terminal = utils.cancelAction(state)">
            Cancel
          </a>
        </div>

      </form>

      <div v-if="state.show_otp">
        <br>
        <verify-otp :callback="editTerminal"></verify-otp>
      </div>

    </div>

  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'
import VerifyOtp from '../verify_otp.vue'
import _ from 'underscore'

export default {
  name: 'update-terminal',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      errors: ''
    }
  },

  props: ['terminal'],

  components: {
    'verify-otp': VerifyOtp
  },

  mounted: function () {
    $('select.dropdown').dropdown()
  },

  methods: {

    editTerminal () {
      var payload = _.pick(this.terminal, ['merchant_name', 'merchant_address', 'merchant_phone', 'merchant_email', 'receipt_text'])
      this.$api.post(url_for('terminals', this.state.sub_id), payload, (data) => {
        this.state.message = { header: 'Success', class: 'success', list: ['Your terminal is updated.'] }
        this.utils.cancelAction(this.state)
        this.utils.scrollToTop()
      }).catch((errors) => {
        this.errors = errors.data
      })
    }
  }

}
</script>
