<template>
  <div>

    <transfer v-if="state.action == 'transfer-bank'" :account="account" :bank_accounts="bank_accounts" :callbacks="callbacks"></transfer>

    <div v-if="state.action == 'bank-balance-inquiry'" class="ui segment">
      <h2 class="ui dividing header">
        Balance inquiry
      </h2>

      <div v-if="!state.show_otp">
        <button class="ui blue submit button"
                :class="{disabled: state.processing}"
                @click.prevent="balanceInquiry()">
          Balance inquiry
        </button>

        <a class="ui basic button" @click="utils.cancelAction(state)">
          Cancel
        </a>
      </div>

      <div v-if="state.show_otp">
        <br>
        <verify-otp :callback="balanceInquiry"></verify-otp>
      </div>

    </div>

  </div>
</template>

<script>
import {url_for} from '../../../constants'
import store from '../../../store'

import VerifyOtp from '../../verify_otp.vue'

import Transfer from './transfer.vue'

export default {

  name: 'bank',

  data () {
    return {
      state: store.state,
      utils: store.utils
    }
  },

  props: ['account', 'callbacks', 'bank_accounts'],

  created: function () {
  },

  components: {
    transfer: Transfer,
    'verify-otp': VerifyOtp
  },

  methods: {
    balanceInquiry () {

      this.$api.post(url_for('transfer/bank-balance-inquiry'), {account_id: this.account.id}).then(
        (response) => {

          this.state.notification = {title: 'Balance is ' + (response.data.balance / 100).toFixed(2) + ' ' + this.account.currency + '.'}
          for (let callback of this.callbacks) { callback() }
          this.utils.cancelAction(this.state)
          this.utils.scrollToTop()
        },
        (response) => {
          if (response.data.status === 'declined') {
            this.state.notification = {title: response.data.response_message,
                                       class: 'error', body: {'Response code': response.data.response_code}}
          } else {
            this.errors = response.data
          }
        }
      )
    }
  }

}
</script>
