/**
 * Form Validation Utility
 *
 * Provides client-side validation functions for forms.
 * IMPORTANT: Client-side validation is for UX only - ALWAYS validate on server!
 *
 * TASK 4: Input Validation
 */

/**
 * Validate email address format
 *
 * @param {string} email - Email address to validate
 * @returns {boolean} - True if valid email format
 *
 * @example
 * validateEmail('user@example.com') // true
 * validateEmail('invalid.email') // false
 */
export function validateEmail (email) {
  if (!email || typeof email !== 'string') {
    return false
  }

  // RFC 5322 compliant email regex
  // Allows most valid email formats while blocking obvious invalid patterns
  const emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/

  return emailRegex.test(email.trim())
}

/**
 * Validate password strength
 *
 * Requirements:
 * - Minimum 8 characters
 * - At least one uppercase letter
 * - At least one lowercase letter
 * - At least one number
 *
 * @param {string} password - Password to validate
 * @returns {object} - {valid: boolean, errors: string[]}
 *
 * @example
 * validatePassword('Pass123!') // {valid: true, errors: []}
 * validatePassword('weak') // {valid: false, errors: ['Password must be at least 8 characters', ...]}
 */
export function validatePassword (password) {
  const errors = []

  if (!password || typeof password !== 'string') {
    return {
      valid: false,
      errors: ['Password is required']
    }
  }

  // Minimum length
  if (password.length < 8) {
    errors.push('Password must be at least 8 characters')
  }

  // Maximum length (prevent DoS)
  if (password.length > 128) {
    errors.push('Password must be less than 128 characters')
  }

  // Must contain uppercase
  if (!/[A-Z]/.test(password)) {
    errors.push('Password must contain at least one uppercase letter')
  }

  // Must contain lowercase
  if (!/[a-z]/.test(password)) {
    errors.push('Password must contain at least one lowercase letter')
  }

  // Must contain number
  if (!/[0-9]/.test(password)) {
    errors.push('Password must contain at least one number')
  }

  return {
    valid: errors.length === 0,
    errors: errors
  }
}

/**
 * Validate monetary amount
 *
 * @param {string|number} amount - Amount to validate (can be formatted with commas/decimals)
 * @param {object} options - Validation options
 * @param {number} options.min - Minimum allowed amount (default: 0.01)
 * @param {number} options.max - Maximum allowed amount (default: 1000000)
 * @param {string} options.currency - Currency code for context (optional)
 * @returns {object} - {valid: boolean, error: string|null, normalized: number|null}
 *
 * @example
 * validateAmount('100.50') // {valid: true, error: null, normalized: 100.50}
 * validateAmount('-50') // {valid: false, error: 'Amount must be positive', normalized: null}
 * validateAmount('1,234.56', {max: 1000}) // {valid: false, error: 'Amount exceeds maximum of 1000', ...}
 */
export function validateAmount (amount, options = {}) {
  const defaults = {
    min: 0.01,
    max: 1000000,
    currency: null
  }

  const opts = { ...defaults, ...options }

  // Convert to string for processing
  const amountStr = String(amount).trim()

  if (!amountStr) {
    return {
      valid: false,
      error: 'Amount is required',
      normalized: null
    }
  }

  // Remove currency formatting (commas, spaces)
  const cleanAmount = amountStr.replace(/[,\s]/g, '')

  // Check if it's a valid number
  if (!/^-?\d+(\.\d{1,2})?$/.test(cleanAmount)) {
    return {
      valid: false,
      error: 'Amount must be a valid number with up to 2 decimal places',
      normalized: null
    }
  }

  const numericAmount = parseFloat(cleanAmount)

  // Check for NaN
  if (isNaN(numericAmount)) {
    return {
      valid: false,
      error: 'Amount must be a valid number',
      normalized: null
    }
  }

  // Must be positive
  if (numericAmount <= 0) {
    return {
      valid: false,
      error: 'Amount must be positive',
      normalized: null
    }
  }

  // Check minimum
  if (numericAmount < opts.min) {
    return {
      valid: false,
      error: `Amount must be at least ${opts.min}`,
      normalized: null
    }
  }

  // Check maximum
  if (numericAmount > opts.max) {
    return {
      valid: false,
      error: `Amount exceeds maximum of ${opts.max}`,
      normalized: null
    }
  }

  return {
    valid: true,
    error: null,
    normalized: numericAmount
  }
}

/**
 * Validate account number format
 *
 * @param {string} accountNumber - Account number to validate
 * @returns {object} - {valid: boolean, error: string|null}
 *
 * @example
 * validateAccountNumber('1234567890') // {valid: true, error: null}
 * validateAccountNumber('abc') // {valid: false, error: 'Account number must be numeric'}
 */
export function validateAccountNumber (accountNumber) {
  if (!accountNumber || typeof accountNumber !== 'string') {
    return {
      valid: false,
      error: 'Account number is required'
    }
  }

  const cleaned = accountNumber.trim()

  // Must be numeric
  if (!/^\d+$/.test(cleaned)) {
    return {
      valid: false,
      error: 'Account number must be numeric'
    }
  }

  // Length validation (typical account numbers are 8-16 digits)
  if (cleaned.length < 6) {
    return {
      valid: false,
      error: 'Account number is too short (minimum 6 digits)'
    }
  }

  if (cleaned.length > 20) {
    return {
      valid: false,
      error: 'Account number is too long (maximum 20 digits)'
    }
  }

  return {
    valid: true,
    error: null
  }
}

/**
 * Validate phone number format
 *
 * @param {string} phone - Phone number with country prefix (e.g., "+1234567890")
 * @returns {object} - {valid: boolean, error: string|null}
 *
 * @example
 * validatePhone('+1234567890') // {valid: true, error: null}
 * validatePhone('123') // {valid: false, error: 'Phone number is too short'}
 */
export function validatePhone (phone) {
  if (!phone || typeof phone !== 'string') {
    return {
      valid: false,
      error: 'Phone number is required'
    }
  }

  const cleaned = phone.trim()

  // Must start with + and contain only digits after that
  if (!/^\+\d+$/.test(cleaned)) {
    return {
      valid: false,
      error: 'Phone number must start with country code (e.g., +1234567890)'
    }
  }

  // Length validation (including country code)
  // Minimum: +1234567 (7 digits) = 8 chars total
  // Maximum: +12345678901234 (14 digits) = 15 chars total
  if (cleaned.length < 8) {
    return {
      valid: false,
      error: 'Phone number is too short (minimum 7 digits)'
    }
  }

  if (cleaned.length > 16) {
    return {
      valid: false,
      error: 'Phone number is too long (maximum 15 digits)'
    }
  }

  return {
    valid: true,
    error: null
  }
}

/**
 * Validate required text field
 *
 * @param {string} value - Text value to validate
 * @param {object} options - Validation options
 * @param {number} options.minLength - Minimum length (default: 1)
 * @param {number} options.maxLength - Maximum length (default: 255)
 * @param {string} options.fieldName - Field name for error messages (default: 'Field')
 * @returns {object} - {valid: boolean, error: string|null}
 *
 * @example
 * validateRequired('John', {fieldName: 'First name'}) // {valid: true, error: null}
 * validateRequired('', {fieldName: 'Last name'}) // {valid: false, error: 'Last name is required'}
 */
export function validateRequired (value, options = {}) {
  const defaults = {
    minLength: 1,
    maxLength: 255,
    fieldName: 'Field'
  }

  const opts = { ...defaults, ...options }

  if (!value || typeof value !== 'string') {
    return {
      valid: false,
      error: `${opts.fieldName} is required`
    }
  }

  const trimmed = value.trim()

  if (trimmed.length < opts.minLength) {
    return {
      valid: false,
      error: `${opts.fieldName} must be at least ${opts.minLength} character${opts.minLength > 1 ? 's' : ''}`
    }
  }

  if (trimmed.length > opts.maxLength) {
    return {
      valid: false,
      error: `${opts.fieldName} must be less than ${opts.maxLength} characters`
    }
  }

  return {
    valid: true,
    error: null
  }
}

/**
 * Validate customer number for bill payment
 *
 * @param {string} customerNumber - Customer number to validate
 * @param {string} operatorCode - Operator code for context (optional)
 * @returns {object} - {valid: boolean, error: string|null}
 *
 * @example
 * validateCustomerNumber('12345678') // {valid: true, error: null}
 * validateCustomerNumber('') // {valid: false, error: 'Customer number is required'}
 */
export function validateCustomerNumber (customerNumber, operatorCode = null) {
  if (!customerNumber || typeof customerNumber !== 'string') {
    return {
      valid: false,
      error: 'Customer number is required'
    }
  }

  const cleaned = customerNumber.trim()

  // Basic length validation
  if (cleaned.length < 3) {
    return {
      valid: false,
      error: 'Customer number is too short (minimum 3 characters)'
    }
  }

  if (cleaned.length > 50) {
    return {
      valid: false,
      error: 'Customer number is too long (maximum 50 characters)'
    }
  }

  // Allow alphanumeric and common separators (-, _, /)
  if (!/^[a-zA-Z0-9\-_/]+$/.test(cleaned)) {
    return {
      valid: false,
      error: 'Customer number contains invalid characters'
    }
  }

  return {
    valid: true,
    error: null
  }
}

/**
 * Validate birth date
 *
 * @param {string} birthDate - Birth date in YYYY-MM-DD format
 * @returns {object} - {valid: boolean, error: string|null}
 *
 * @example
 * validateBirthDate('1990-01-15') // {valid: true, error: null}
 * validateBirthDate('2050-01-01') // {valid: false, error: 'Birth date cannot be in the future'}
 */
export function validateBirthDate (birthDate) {
  if (!birthDate || typeof birthDate !== 'string') {
    return {
      valid: false,
      error: 'Birth date is required'
    }
  }

  // Check format YYYY-MM-DD
  if (!/^\d{4}-\d{2}-\d{2}$/.test(birthDate)) {
    return {
      valid: false,
      error: 'Birth date must be in YYYY-MM-DD format'
    }
  }

  const date = new Date(birthDate)
  const today = new Date()

  // Check if valid date
  if (isNaN(date.getTime())) {
    return {
      valid: false,
      error: 'Birth date is not a valid date'
    }
  }

  // Cannot be in the future
  if (date > today) {
    return {
      valid: false,
      error: 'Birth date cannot be in the future'
    }
  }

  // Must be at least 18 years old
  const eighteenYearsAgo = new Date()
  eighteenYearsAgo.setFullYear(today.getFullYear() - 18)

  if (date > eighteenYearsAgo) {
    return {
      valid: false,
      error: 'You must be at least 18 years old'
    }
  }

  // Cannot be more than 120 years ago
  const maxAge = new Date()
  maxAge.setFullYear(today.getFullYear() - 120)

  if (date < maxAge) {
    return {
      valid: false,
      error: 'Birth date is not valid'
    }
  }

  return {
    valid: true,
    error: null
  }
}

export default {
  validateEmail,
  validatePassword,
  validateAmount,
  validateAccountNumber,
  validatePhone,
  validateRequired,
  validateCustomerNumber,
  validateBirthDate
}
