<template>
  <div>

    <h3 class="ui dividing header">Uploaded documents</h3>

    <table class="ui celled compact single line table">
      <thead>
        <tr>
          <th>Type</th>
          <th>Status</th>
          <th>Comment</th>
          <th>Uploaded at</th>
        </tr>
      </thead>

      <tbody v-if="documents.length == 0">
        <tr>
          <td colspan="4">No uploaded documents yet.</td>
        </tr>
      </tbody>

      <tbody v-else>
        <tr v-for="(d, index) in documents" :key="d.id">
          <td>{{types[d.type]}}</td>
          <td :class="{'green': d.status == 'approved', 'red': d.status == 'rejected'}">
            {{d.status | capitalize}}
          </td>
          <td style="white-space: normal;">{{d.comment}}</td>
          <td>{{d.created_at | displayDate}}</td>
        </tr>
      </tbody>
    </table>

  </div>
</template>

<script>

import {url_for, document_types} from '../../constants'
import store from '../../store'

export default {
  name: 'documents',

  data () {
    return {
      state: store.state,
      utils: store.utils,
      documents: [],
      types: document_types
    }
  },

  created: function () {
    this.getDocuments()
  },

  methods: {

    getDocuments () {
      this.$api.get(url_for('profile/documents')).then(
        (response) => {
          this.documents = response.data
        },
        (response) => {console.log(response.data)}
      )
    }
  }
}
</script>