<template>
  <div class="ui basic segment">

    <form class="ui form" autocomplete="false">

      <h3 class="ui dividing header">Terminal #{{terminal.id}}: New cashier</h3>

      <div class="two fields">
        <div class="field" :class="{ error: errors.full_name }">
          <label>Full name</label>
          <input  placeholder="Enter full name"
                  type="text"
                  v-model="cashier.full_name"><br>
          <div v-if="errors.full_name" class="ui basic red pointing prompt label transition visible">{{errors.full_name[0]}}</div>
        </div>
      </div>

      <div class="inline field" :class="{ error: errors.manager }">
        <div class="ui checkbox">
          <input  type="checkbox"
                  v-model="cashier.manager"
                  v-bind:true-value="true"
                  v-bind:false-value="false">
          <label>Manager</label>
        </div>
        <div v-if="errors.manager" class="ui basic red pointing prompt label transition visible">{{errors.manager[0]}}</div>
      </div>

      <div v-if="!state.show_otp">
        <button class="ui blue submit button"
                :class="{disabled: state.processing}"
                @click.prevent="createCashier()">
          Create cashier
        </button>

        <a class="ui basic button" @click="utils.showSubAction(state, 'cashiers')">
          Cancel
        </a>
      </div>

    </form>

    <div v-if="state.show_otp">
      <br>
      <verify-otp></verify-otp>
    </div>

  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'
import VerifyOtp from '../verify_otp.vue'
// import _ from 'underscore'

export default {
  name: 'update-cashier',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      cashier: {manager: false},
      pin: '',
      errors: ''
    }
  },

  props: ['terminal'],

  components: {
    'verify-otp': VerifyOtp
  },

  mounted: function () {
    $('.ui.checkbox').checkbox()
  },

  methods: {
    createCashier () {
      this.$api.post(url_for('terminals', this.terminal.id, 'cashiers/create'), this.cashier).then(
        (response) => {
          this.state.notification = {title: 'Cashier PIN is ' + response.data.pin + '.'}
          this.utils.cancelAction(this.state)
          this.utils.scrollToTop()
        },
        (response) => {this.errors = response.data}
      )
    }
  }

}
</script>