<template>
  <div class="lod-print">

    <h2 class="ui dividing header">
      Terminal #{{lodgment.terminal.id}}: Lodgment summary report

      <div class="ui basic button right floated" @click="utils.cancelAction(state, false)">
        Close
      </div>
      <div class="ui basic button right floated" @click="print()">
        <i class="print icon"></i>Print
      </div>
      <div class="sub header">
        Lodgment No. <strong>{{lodgment.batch_number}}</strong> |
        Starting time: <strong>{{lodgment.started_at | displayDate}}</strong> |
        Closing time: <strong>{{lodgment.created_at | displayDate}}</strong>
      </div>
    </h2>

    <br>
    <div class="ui basic segment">
      <div class="ui six tiny statistics">
        <div class="statistic">
          <div class="value">
            {{utils.toCurrency(total, currency)}}
          </div>
          <div class="label">
            Sales amount
          </div>
        </div>
        <div class="statistic">
          <div class="value">
            {{sales_count}}
          </div>
          <div class="label">
            Sales count
          </div>
        </div>

        <div class="orange statistic">
          <div class="value">
            {{utils.toCurrency(reversals_total, currency)}}
          </div>
          <div class="label">
            Reversal amount
          </div>
        </div>
        <div class="orange statistic">
          <div class="value">
            {{reversals_count}}
          </div>
          <div class="label">
            Reversal count
          </div>
        </div>

        <div class="statistic">
          <div class="value">
            {{utils.toCurrency(topup_total, currency)}}
          </div>
          <div class="label">
            Top-up amount
          </div>
        </div>
        <div class="statistic">
          <div class="value">
            {{topup_count}}
          </div>
          <div class="label">
            Top-up  count
          </div>
        </div>
      </div>
    </div>
    <br>

    <p>
      <button :class="{'disabled': display == 'default'}" class="ui basic blue small button" @click.prevent="display = 'default'">
        Default view
      </button>
      <button :class="{'disabled': display == 'per_p_method'}" class="ui basic blue small button" @click.prevent="display = 'per_p_method'">
        Totals per payment method
      </button>
      <button :class="{'disabled': display == 'per_p_type'}" class="ui basic blue small button" @click.prevent="display = 'per_p_type'">
        Totals per payment method type
      </button>
      <button :class="{'disabled': display == 'per_cashier'}" class="ui basic blue small button" @click.prevent="display = 'per_cashier'">
        Totals per cashier
      </button>
    </p>

    <div v-if="display == 'default'" class="ui stackable grid">
      <div class="eight wide column">
        <table class="ui very basic compact table right aligned">
          <thead>
            <tr class="pointer">
              <th class="left aligned">Bill payment</th>
              <th>Reversal count</th>
              <th>Reversal amount</th>
              <th>Sales count</th>
              <th>Sales amount</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="(t, index) in sortedBillTrxs" :key="t.operator_code">
              <td class="left aligned">{{state.operators.by_code[t.operator_code]}}</td>
              <td :class="{'red': bill_reversal_trxs[index].count}">{{bill_reversal_trxs[index].count}}</td>
              <td :class="{'red': bill_reversal_trxs[index].amount}">
                - {{utils.toCurrency(bill_reversal_trxs[index].amount, currency)}}
              </td>
              <td>{{t.count}}</td>
              <td>{{utils.toCurrency(t.amount, currency)}}</td>
            </tr>
          </tbody>
          <tfoot>
            <tr>
              <th class="left aligned"><strong>Totals</strong></th>
              <th :class="{'red': bill_reversals_count}"><strong>{{bill_reversals_count}}</strong></th>
              <th><strong class="red"> - {{utils.toCurrency(bill_reversals_total, currency)}}</strong></th>
              <th><strong>{{bill_count}}</strong></th>
              <th><strong>{{utils.toCurrency(bill_total, currency)}}</strong></th>
            </tr>
          </tfoot>
        </table>
      </div>

      <div class="eight wide column">
        <table class="ui very basic compact table right aligned">
          <thead>
            <tr>
              <th class="left aligned" width="30%">Prepaid</th>
              <th>Sales count</th>
              <th>Sales amount</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td class="left aligned">Pagatinu</td>
              <td>{{prepaid_count}}</td>
              <td>
                {{utils.toCurrency(prepaid_total, currency)}}<br>
              </td>
            </tr>
          </tbody>
          <tfoot>
            <tr>
              <th class="left aligned"><strong>Totals</strong></th>
              <th><strong>{{prepaid_count}}</strong></th>
              <th><strong>{{utils.toCurrency(prepaid_total, currency)}}</strong></th>
            </tr>
          </tfoot>
        </table>

        <table class="ui very basic compact table right aligned">
          <thead>
            <tr class="pointer">
              <th class="left aligned">e-Voucher</th>
              <th>Sales count</th>
              <th>Sales amount</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="(t, index) in voucher_trxs" :key="t.name">
              <td class="left aligned">{{t.name}}</td>
              <td>{{t.count}}</td>
              <td>
                {{utils.toCurrency(t.amount, currency)}}<br>
              </td>
            </tr>
          </tbody>
          <tfoot>
            <tr>
              <th class="left aligned"><strong>Totals</strong></th>
              <th><strong>{{voucher_count}}</strong></th>
              <th><strong>{{utils.toCurrency(voucher_total, currency)}}</strong></th>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>


    <div v-else class="ui stackable grid">
      <div class="sixteen wide column">
        <table class="ui very basic compact table right aligned">
          <thead>
            <tr class="pointer">
              <th class="left aligned">Bill payment</th>
              <th>Sales count</th>
              <th>Sales amount</th>
            </tr>
          </thead>
          <tbody>
            <tr v-for="t in breakdown_trxs" :key="index">
              <td class="left aligned">
                <template v-if="display == 'per_cashier'">
                  {{t.full_name}}
                </template>
                <template v-if="display == 'per_p_method'">
                  {{constants.trx_payment_methods[t.payment_method].name}}
                </template>
                <template v-if="display == 'per_p_type'">
                  <template v-if="t.payment_method_type == ''">Cash (no type)</template>
                  <template v-else>
                    {{utils._.extend(constants.trx_payment_methods.card.types, constants.trx_payment_methods.check.types)[t.payment_method_type]}}
                  </template>
                </template>
              </td>
              <td>{{t.count}}</td>
              <td>{{utils.toCurrency(t.amount, currency)}}</td>
            </tr>
          </tbody>
          <tfoot>
            <tr>
              <th class="left aligned"><strong>Totals</strong></th>
              <th><strong>{{bill_count}}</strong></th>
              <th><strong>{{utils.toCurrency(bill_total, currency)}}</strong></th>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>

    <a class="ui basic button" @click="utils.cancelAction(state, false)">
      Close
    </a>

  </div>
</template>

<script>

import store from '../../store'
import {url_for} from '../../constants'
import _ from 'underscore'

export default {
  name: 'services-lodgment-details',

  data () {
    return {
      state: store.state,
      utils: store.utils,
      constants: store.state.constants,
      currency: '',
      display: 'default',

      // voucher
      voucher_trxs: [],
      voucher_total: 0,
      voucher_count: 0,

      // bill
      bill_trxs: [],
      bill_total: 0,
      bill_count: 0,

      // bill reversal
      bill_reversal_trxs: [],
      bill_reversals_total: 0,
      bill_reversals_count: 0,

      // topups
      topup_total: 0,
      topup_count: 0,

      // prepaid
      prepaid_total: 0,
      prepaid_count: 0,

      // total amounts
      total: 0,
      reversals_total: 0,

      // total counts
      sales_count: 0,
      reversals_count: 0,

      // per attr
      breakdown_trxs: [],
      bills_per_payment_method: [],
      bills_per_payment_method_type: [],
      bills_per_cashier: [],

      // data
      stats: {transactions_count: 0}
    }
  },

  props: ['account', 'lodgment'],

  created: function () {
    this.$api.post(url_for('accounts', this.account.id, 'services-lodgments', this.lodgment.id, 'show'), {terminal_id: this.lodgment.terminal_id, services_batch_number: this.lodgment.batch_number}).then(
      function (response) {
        this.currency = this.lodgment.currency
        this.stats = response.data

        // bill
        this.bill_total = this.utils.sumArray(this.stats.bill_trxs, 'amount')
        this.bill_count = this.utils.sumArray(this.stats.bill_trxs, 'count')

        // bill reversals
        this.bill_reversals_total = this.utils.sumArray(this.stats.bill_reversal_trxs, 'amount')
        this.bill_reversals_count = this.utils.sumArray(this.stats.bill_reversal_trxs, 'count')

        // voucher
        this.voucher_total = this.utils.sumArray(this.stats.voucher_trxs, 'amount')
        this.voucher_count = this.utils.sumArray(this.stats.voucher_trxs, 'count')

        // topups
        this.topup_total = this.stats.topup_trxs.amount
        this.topup_count = this.stats.topup_trxs.count

        // prepaid
        this.prepaid_total = this.stats.prepaid_trxs.amount
        this.prepaid_count = this.stats.prepaid_trxs.count

        // total amounts
        this.reversals_total = this.bill_reversals_total
        this.total = this.voucher_total + this.bill_total + this.prepaid_total

        // total counts
        this.sales_count = this.bill_count + this.voucher_count + this.prepaid_total
        this.reversals_count = this.bill_reversals_count

        // per attr
        this.bill_trxs_per_payment_method = this.stats.bills_per_payment_method
        this.bill_trxs_per_payment_method_type = this.stats.bills_per_payment_method_type
        this.bill_trxs_per_cashier = this.stats.bills_per_cashier

        // map operators/product to records to display zero totals for non-existent records
        this.voucher_trxs = _.map(this.state.products, function (p) {
          return this.utils.findItemByKeyAndValue(this.stats.voucher_trxs, 'name', p.name) || {name: p.name, count: 0, amount: 0}
        }.bind(this))

        this.bill_trxs = _.map(this.state.operators.bill, function (o) {
          return this.utils.findItemByKeyAndValue(this.stats.bill_trxs, 'operator_code', o.code) || {operator_code: o.code, count: 0, amount: 0}
        }.bind(this))

        this.bill_reversal_trxs = _.map(this.state.operators.bill, function (o) {
          return this.utils.findItemByKeyAndValue(this.stats.bill_reversal_trxs, 'operator_code', o.code) || {operator_code: o.code, count: 0, amount: 0}
        }.bind(this))
      },
      (response) => {console.log(response.data)}
    )
  },

  computed: {
    sortedBillTrxs() {
      if (!this.bill_trxs) return []
      return [...this.bill_trxs].sort((a, b) => {
        return (a.operator_code || '').localeCompare(b.operator_code || '')
      })
    }
  },

  watch: {
    display: function () {
      if (this.display === 'per_p_method') {this.breakdown_trxs = this.bill_trxs_per_payment_method}
      if (this.display === 'per_p_type') {this.breakdown_trxs = this.bill_trxs_per_payment_method_type}
      if (this.display === 'per_cashier') {this.breakdown_trxs = this.bill_trxs_per_cashier}
    }
  },

  methods: {
    showTransactions (l) {
      this.state.addFilter('business_transaction', 'terminal_id', l.terminal_id, 'Terminal: ' + l.terminal.merchant_name)
      this.state.addFilter('business_transaction', 'services_batch_number', l.batch_number, 'Lodgment No: ' + l.batch_number)
    },

    print () {
      $('.lod-print').printThis()
    }
  }

}
</script>
