<template>
  <div class="ui segment">
    <h2 class="ui dividing header">
      Transfer funds to other wallet account
      <div class="sub header">{{utils.showFee('transfer', account, state)}}</div>
    </h2>

    <form class="ui form" autocomplete="false">

      <div class="fields">

        <div class="five wide field">
          <label>Find account by</label>

          <div class="ui fluid basic floating dropdown button">
            <div class="text">Select</div>
            <i class="dropdown icon"></i>
            <div class="menu">
              <div class="item" @click="findBy('account_number')">{{search_by.account_number | capitalize}}</div>
              <div class="item" @click="findBy('phone')">{{search_by.phone | capitalize}}</div>
              <div class="item" @click="findBy('email')">{{search_by.email | capitalize}}</div>
              <div class="divider"></div>
              <div class="item" @click="findBy('history')">{{search_by.history | capitalize}}</div>
            </div>
          </div>
        </div>

        <div class="seven wide field" :class="{ error: errors.target_account_id }">
          <label>Select account</label>

          <div class="ui icon input" id="search">

            <input v-if="account_finder != 'history'" type="text" v-model="term"
              :placeholder="search_by[account_finder] ? 'Enter ' + search_by[account_finder]: 'Select find method'"
              @input="debouncedFindAccounts" @blur="closePopup()"
              @click="redisplayPopup()" :disabled="!account_finder">

            <input v-else type="text" v-model="term" placeholder="Select account from history"
              @blur="closePopup()" @click="redisplayPopup()">

            <i class="search icon"></i>
          </div>

          <div class="ui popup vertical menu in-field-6 transition hidden">
            <template v-if="accounts.length">
              <a v-for="a in accounts" :key="a.id" @click="chooseAccount(a)" class="item">
                <ul class="ui bulleted list">
                  <li>Owner: <strong>{{a.users[0].first_name}} {{a.users[0].last_name}}</strong></li>
                  <li>Account type: <strong>{{state.constants.account_types[a.type]}}</strong></li>
                  <li>Account number:<strong> #{{a.account_number}}</strong></li>
                </ul>
              </a>
            </template>
            <p v-if="!accounts.length" style="padding: 1em;">
              <strong>No result</strong>
              <br>Your input returned no result
            </p>
          </div>

          <div v-if="errors.target_account_id" class="ui basic red pointing prompt label transition visible">{{errors.target_account_id[0]}}</div>
        </div>


        <div class="four wide field" :class="{ error: errors.amount }">
          <label>Amount</label>

          <div class="ui left labeled input">
            <div class="ui label">{{account.currency}}</div>
            <input  placeholder="Enter amount"
                    type="text"
                    v-model="transfer.amount"
                    maxlength="9"
                    id="currency">
          </div><br>
          <div v-if="errors.amount" class="ui basic red pointing prompt label transition visible">{{errors.amount[0]}}</div>
        </div>
      </div>

      <div class="field hide" :class="{ error: errors.target_account_id }">
        <label>Account number</label>
        <input  placeholder="Enter account number"
                type="text"
                v-model="transfer.target_account_id"><br>
        <div v-if="errors.target_account_id" class="ui basic red pointing prompt label transition visible">{{errors.target_account_id[0]}}</div>
      </div>

      <div class="field" :class="{ error: errors.note }">
        <label>Transfer note</label>
        <input  placeholder="Enter transfer note"
                type="text"
                v-model="transfer.note"><br>
        <div v-if="errors.note" class="ui basic red pointing prompt label transition visible">{{errors.note[0]}}</div>
      </div>

      <div v-if="!state.show_otp">
        <button class="ui blue submit button"
                :class="{disabled: state.processing}"
                @click.prevent="transferFunds()">
          Transfer
        </button>

        <a class="ui basic button" @click="utils.cancelAction(state)">
          Cancel
        </a>
      </div>

    </form>

    <div v-if="state.show_otp">
      <br>
      <verify-otp :callback="transferFunds"></verify-otp>
    </div>

  </div>
</template>

<script>

import {url_for} from '../../../constants'
import store from '../../../store'

import VerifyOtp from '../../verify_otp.vue'

import _ from 'underscore'
import { validateAmount } from '../../../utils/validation'

export default {
  name: 'transfer',

  data () {
    return {
      utils: store.utils,
      state: store.state,

      // account selection
      search_by: {account_number: 'account number', phone: 'phone number', email: 'email address', history: 'choose from history'},
      account_finder: false,
      accounts: [],
      term: '',

      transfer: {},
      errors: ''
    }
  },

  props: ['account', 'callbacks'],

  components: {
    'verify-otp': VerifyOtp
  },

  created: function () {
    // Create debounced version of findAccounts early so it's available in template
    this.debouncedFindAccounts = _.debounce(this.findAccounts, 500)
  },

  mounted: function () {
    try {
      if ($ && $.fn && $.fn.dropdown) {
        $('.ui.dropdown').dropdown()
      }
      if ($ && $.fn && $.fn.checkbox) {
        $('.ui.checkbox').checkbox()
      }
    } catch (e) {
      // Semantic UI not loaded yet
    }
    $('#currency').maskMoney()
    this.transfer.currency = this.account.currency
    this.transfer.source_account_id = this.account.id
    $('#search').popup({on: 'manual', inline: true, position: 'bottom left',
      distanceAway: 1, lastResort: 'bottom left', hideOnScroll: false})
  },

  watch: {
    'account_finder': function () {
      if (this.account_finder === 'history') {this.loadHistory()}
    }
  },

  methods: {

    validateTransfer () {
      // Client-side validation before submitting
      this.errors = {}
      let isValid = true

      // Validate amount
      if (!this.transfer.amount) {
        this.errors.amount = ['Amount is required']
        isValid = false
      } else {
        const amountResult = validateAmount(this.transfer.amount, {
          min: 0.01,
          max: 1000000
        })
        if (!amountResult.valid) {
          this.errors.amount = [amountResult.error]
          isValid = false
        }
      }

      // Validate target account
      if (!this.transfer.target_account_id) {
        this.errors.target_account_id = ['Please select a target account']
        isValid = false
      }

      return isValid
    },

    transferFunds () {
      // Validate before submitting
      if (!this.validateTransfer()) {
        return
      }

      this.$api.post(url_for('transfer'), this.utils.currencyToCents(_.clone(this.transfer), ['amount'])).then(
        (response) => {
          this.state.notification = {title: 'Funds are transferred to account #' + this.transfer.target_account_id + '.'}
          this.utils.cancelAction(this.state)
          for (let callback of this.callbacks) { callback() }
          this.utils.scrollToTop()
        },
        (response) => {this.errors = response.data}
      )
    },

    findBy (method) {
      this.account_finder = method
      this.accounts = []
      this.term = ''
      this.transfer.target_account_id = ''
      $('#search').popup('hide')
    },

    findAccounts () {
      if (this.term.length < 3) {return}
      $('#search').popup('show')

      var search = {}
      search[this.account_finder] = this.term

      this.$api.post(url_for('find-accounts', this.account_finder), {search: search}).then(
        (response) => {
          this.accounts = response.data
        },
        (response) => {
          this.errors = response.data
          this.accounts = []
        }
      )

    },

    chooseAccount (account) {
      this.transfer.target_account_id = account.account_number
      this.term = 'Account: #' + account.account_number + '   Owner: ' + account.users[0].first_name + ' ' + account.users[0].last_name
      $('#search').popup('hide')
    },

    closePopup () {
      $('#search').popup('hide')
    },

    redisplayPopup () {
      if (this.accounts.length) {$('#search').popup('show')}
    },

    loadHistory () {
      this.$api.get(url_for('transactions/transfer-history')).then(
        (response) => {
          this.accounts = response.data
          $('#search').popup('show')
        },
        (response) => {
          this.errors = response.data
          this.accounts = []
        }
      )
    }
  }

}
</script>
