<template>
  <div>

    <h3 class="ui dividing header">Edit profile</h3>

    <form class="ui form" autocomplete="false">

      <div class="two fields">
        <div class="field" :class="{ error: errors.first_name }">
          <label>First name</label>
          <input  placeholder="Enter your first name"
                  type="text"
                  v-model="profile.first_name"
                  disabled>
          <div v-if="errors.first_name" class="ui basic red pointing prompt label transition visible">{{errors.first_name[0]}}</div>
        </div>

        <div class="field" :class="{ error: errors.last_name }">
          <label>Last name</label>
          <input  placeholder="Enter your last name"
                  type="text"
                  v-model="profile.last_name"
                  disabled>
          <div v-if="errors.last_name" class="ui basic red pointing prompt label transition visible">{{errors.last_name[0]}}</div>
        </div>
      </div>

      <div class="two fields">
        <div class="field" :class="{ error: errors.birth_date }">
          <label>Birth date</label>
          <input  placeholder="Enter your birth date"
                  type="date"
                  v-model="profile.birth_date"
                  disabled>
          <div v-if="errors.birth_date" class="ui basic red pointing prompt label transition visible">{{errors.birth_date[0]}}</div>
        </div>

        <div class="field" :class="{ error: errors.address }">
          <label>Address</label>
          <input  placeholder="Enter your address"
                  type="text"
                  v-model="profile.address">
          <div v-if="errors.address" class="ui basic red pointing prompt label transition visible">{{errors.address[0]}}</div>
        </div>
      </div>

      <div class="two fields">
        <div class="field" :class="{ error: errors.city }">
          <label>City</label>
          <input  placeholder="Enter your city"
                  type="text"
                  v-model="profile.city">
          <div v-if="errors.city" class="ui basic red pointing prompt label transition visible">{{errors.city[0]}}</div>
        </div>

        <div class="field" :class="{ error: errors.zip }">
          <label>Zip code</label>
          <input  placeholder="Enter your zip code"
                  type="text"
                  v-model="profile.zip">
          <div v-if="errors.zip" class="ui basic red pointing prompt label transition visible">{{errors.zip[0]}}</div>
        </div>
      </div>

      <div class="two fields">
        <div class="field" :class="{ error: errors.country }">
          <label>Country</label>
          <select class="ui search dropdown" v-model="profile.country" autocomplete="false">
            <option value="">Select Country</option>
            <option v-for="(country, key) in countries" :value="key" :key="key">
              {{ country[0] }}
            </option>
          </select>
          <div v-if="errors.country" class="ui basic red pointing prompt label transition visible">{{errors.country[0]}}</div>
        </div>

        <div class="field" :class="{ error: errors.phone }">
          <label>Mobile phone number</label>
          <div class="ui left labeled input">
            <div class="ui basic label">
              +{{phone_prefix}}
            </div>
            <input type="text" placeholder="Enter your mobile phone number" v-model="partial_phone">
          </div>
          <div v-if="errors.phone" class="ui basic red pointing prompt label transition visible">{{errors.phone[0]}}</div>
        </div>
      </div>

      <div class="two fields">
        <div class="field" :class="{ error: errors.password }">
          <label>New password</label>
          <input  placeholder="Enter new password"
                  type="password"
                  v-model="password">
          <div v-if="errors.password" class="ui basic red pointing prompt label transition visible">{{errors.password[0]}}</div>
        </div>

        <div class="field" :class="{ error: !password_match }">
          <label>New password confirmation</label>
          <input  placeholder="Enter new password"
                  type="password"
                  v-model="password_confirmation">
          <div v-if="!password_match" class="ui basic red pointing prompt label transition visible">does not match password</div>
        </div>
      </div>

      <button v-if="!state.show_otp"
              class="ui blue submit button"
              :class="{disabled: state.processing}"
              @click.prevent="updateProfile()">
        Edit profile
      </button>

      <a v-if="!state.show_otp" class="ui basic button" @click="utils.cancelAction(state)">
        Cancel
      </a>

    </form>

    <div v-if="state.show_otp">
      <br>
      <verify-otp :callback="updateProfile"></verify-otp>
    </div>

  </div>
</template>

<script>
import {url_for} from '../../constants'
import {countries} from '../../constants'
import store from '../../store'
import VerifyOtp from '../verify_otp.vue'
import _ from 'underscore'

export default {
  name: 'update-profile',

  data () {
    return {
      state: store.state,
      utils: store.utils,

      // profile send to server
      profile: {
        title: '',
        first_name: '',
        last_name: '',
        address: '',
        city: '',
        zip: '',
        country: '',
        phone: '',
        email: ''
      },

      // errors returned from server
      errors: '',

      // passwords
      password: '',
      password_confirmation: '',

      // phone
      phone: '',
      partial_phone: '',
      phone_prefix: '',

      // countries
      countries: ''

    }
  },

  components: {
    'verify-otp': VerifyOtp
  },

  created: function () {
    this.countries = countries
    this.profile = _.clone(this.state.profile)
    this.phone_prefix = this.countries[this.profile.country][1]
    this.partial_phone = this.profile.phone.slice(this.phone_prefix.length)
  },

  mounted: function () {
    $('select.dropdown').dropdown('set selected', this.profile.country)
  },

  watch: {

    'profile.country': function () {
      this.phone_prefix = this.countries[this.profile.country][1]
    },

    phone: function () {
      this.profile.phone = this.phone
    }
  },

  computed: {

    password_match: function () {
      return this.password === this.password_confirmation
    },

    phone: function () {
      return this.phone_prefix + this.partial_phone
    }
  },

  methods: {
    updateProfile () {

      // block if not password_match
      if (!this.password_match) {
        return
      }

      // password is optional
      var payload = _.pick(this.profile, ['address', 'zip', 'city', 'country', 'phone'])
      if (this.password) { payload = _.extend(payload, {password: this.password}) }

      this.$api.post(url_for('profile', 'update'), payload, (data) => {
        this.state.profile = this.profile
        this.state.message = { header: 'Success', class: 'success', list: ['Your profile is updated.'] }
        this.utils.cancelAction(this.state)
      }).catch((errors) => {
        this.errors = errors.data
      })
    }
  }

}
</script>
