<template>
  <div>

    <div v-if="state.action == 'details'">
      <details :account="account" :lodgment="selected"></details>
    </div>

    <div v-show="!state.action">
      <p>
        <a class="ui basic small blue button" @click="lodgments_switch = !lodgments_switch">
          <i class="list layout icon"></i> Transactions
        </a>
        <a class="ui basic small button" @click="getLodgments()">
          <i class="refresh icon"></i> Refresh data
        </a>
        <a class="ui basic small button" @click="search.active = !search.active">
          <i class="search icon"></i> Search
        </a>
      </p>

      <form id="search" v-show="search.active" class="ui form segment" autocomplete="false">

        <div class="three fields">
          <div class="field">
            <label>Lodgment number</label>
            <input  placeholder="Enter lodgment number"
                    type="text"
                    v-model="search.q.batch_number"><br>
          </div>

          <div class="field">
            <label>Date before</label>
            <input  placeholder="Select date"
                    type="text"
                    @click="utils.setKeyFromInputValue(search.q, 'created_at_lt', $event)"
                    class="flatpickr"
                    data-maxdate="today"
                    v-model="search.q.created_at_lt"><br>
          </div>

          <div class="field">
            <label>Date after</label>
            <input  placeholder="Select date"
                    type="text"
                    @click="utils.setKeyFromInputValue(search.q, 'created_at_gt', $event)"
                    class="flatpickr"
                    data-maxdate="today"
                    v-model="search.q.created_at_gt"><br>
          </div>
        </div>

        <div class="three fields">

          <div class="field">
            <label>Amount</label>
            <input  placeholder="Enter amount"
                    type="text"
                    v-model="search.q.batch_amount"><br>
          </div>

          <div class="field">
            <label>Amount greater than</label>
            <input  placeholder="Enter amount"
                    type="text"
                    v-model="search.q.batch_amount_gt"><br>
          </div>

          <div class="field">
            <label>Amount less than</label>
            <input  placeholder="Enter amount"
                    type="text"
                    v-model="search.q.batch_amount_lt"><br>
          </div>
        </div>

        <button class="ui blue submit button"
                :class="{disabled: state.processing}"
                @click.prevent="state.doSearch('services_lodgment', current_page, getLodgments)">
          Search
        </button>
        <button class="ui basic clear button" @click.prevent="state.cancelSearch('services_lodgment', getLodgments)">
          Reset search
        </button>
        <a class="ui basic button" @click="state.cancelSearch('services_lodgment')">
          Cancel
        </a>

      </form>

      <i id="arrow" v-show="attr" :class="direction == -1 ? 'down' : 'up'" class="angle icon"></i>

      <table class="ui celled compact single line selectable table right aligned">
        <thead>
          <tr :class="{'disabled': state.id, 'pointer': !state.id }">
            <th @click="reorder('id', $event)" class="left aligned">#Id</th>
            <th @click="reorder('terminal_id', $event)">Terminal</th>
            <th @click="reorder('started_at', $event)">Starting time</th>
            <th @click="reorder('created_at', $event)">Closing time</th>
            <th @click="reorder('cashier.full_name', $event)">Cashier</th>
            <th @click="reorder('batch_number', $event)">Lodgment No.</th>
            <th @click="reorder('batch_limit', $event)">Credit limit</th>
            <th @click="reorder('batch_amount', $event)">Amount</th>
          </tr>
        </thead>

        <tbody v-if="lodgments.length == 0">
          <tr>
            <td class= "left aligned" colspan="8">
              No lodgments.
            </td>
          </tr>
        </tbody>

        <tbody v-else class="pointer">
          <template v-for="l in sortedLodgments">
            <tr :key="l.id" @click.prevent="select(l)">
              <td class="left aligned">{{l.id}}</td>
              <td>
                #{{l.terminal_id}}
              </td>
              <td>{{l.started_at | displayDate}}</td>
              <td>{{l.created_at | displayDate}}</td>
              <td>{{l.cashier.full_name}}</td>
              <td>{{l.batch_number}}</td>
              <td>{{utils.toCurrency(l.account.credit_limit, l.currency)}}</td>
              <td>{{utils.toCurrency(l.batch_amount, l.currency)}}</td>
            </tr>
          </template>
        </tbody>

        <tfoot v-if="0 || total_pages > 1">
          <tr>
            <th colspan="8">
              <embeded-paginator :total_pages="total_pages" :current_page.sync="current_page" :gap_treshold="gap_treshold"></embeded-paginator>
            </th>
          </tr>
        </tfoot>
      </table>
    </div>

  </div>
</template>

<script>
import {url_for} from '../../constants'
import store from '../../store'

import EmbededPaginator from './../shared/embeded_paginator.vue'
import Details from './details.vue'

import flatpickr from 'flatpickr'

export default {
  name: 'services-lodgments',

  data () {
    return {
      state: store.state,
      utils: store.utils,
      url_for: url_for,

      lodgments: [],
      selected: false,

      // pagination
      count: 0,
      gap_treshold: 5,
      per_page: null,
      total_pages: null, // this will be computed from response when mounted
      current_page: 1,

      // ordering
      attr: false,
      direction: -1,

      // search
      search: store.state.search.services_lodgment
    }
  },

  props: ['account', 'lodgments_switch'],

  components: {
    'embeded-paginator': EmbededPaginator,
    details: Details
  },

  route: {
    canReuse: false
  },

  created: function () {
    this.getLodgments()
  },

  mounted: function () {
    $('select.dropdown').dropdown()
    flatpickr('.flatpickr')
  },

  computed: {
    sortedLodgments() {
      if (!this.lodgments || !this.attr) return this.lodgments
      return [...this.lodgments].sort((a, b) => {
        let aVal = a[this.attr]
        let bVal = b[this.attr]
        if (aVal < bVal) return -1 * this.direction
        if (aVal > bVal) return 1 * this.direction
        return 0
      })
    }
  },

  watch: {
    current_page: function () {
      this.getLodgments()
    }
  },

  methods: {
    select (l) {
      this.state.action = 'details'
      this.selected = l
    },

    getLodgments () {
      this.$api.post(url_for('accounts', this.account.id, 'services-lodgments', this.current_page), this.state.searchParams('services_lodgment')).then(
        function (response) {
          this.count = response.headers('x-total-count')
          this.per_page = response.headers('x-per-page')
          this.lodgments = response.data
          this.total_pages = Math.ceil(this.count / this.per_page)
        },
        (response) => {console.log(response.data)}
      )
    },

    reorder (attr, e) {
      this.attr = attr
      this.direction = this.direction * -1
      $(e.target).append($('#arrow'))
    }

  }

}
</script>
