<template>
  <div>

    <h3 class="ui dividing header">Notification settings</h3>

    <a v-show="!add_notification" class="ui basic button" @click="add_notification = !add_notification">
      Add/edit notification
    </a>

    <div v-show="add_notification" class="ui segment">

      <h4 class="ui dividing header">Add or edit notification</h4>

      <form class="ui form" autocomplete="false">
        <div class="field">
          <label>Transaction type</label>
          <select v-model="trx_type" class="ui dropdown" @change="setActive()">
            <option value="">Select type</option>
            <option v-for="(type, key) in state.constants.trx_transaction_types.wallet.types" :value="key" :key="key">{{type}}</option>
          </select><br>
        </div>

        <div class="inline field">
          <div class="ui checkbox">
            <input  type="checkbox"
                    v-model="active"
                    v-bind:true-value="true"
                    v-bind:false-value="false">
            <label>Active</label>
          </div>
        </div>

        <p>
          <a class="ui blue submit button"
                  :class="{disabled: state.processing}"
                  @click="updateSettings()">
            Add/edit notification
          </a>
          <a class="ui basic button" @click="add_notification = !add_notification">
            Cancel
          </a>
        </p>
      </form>
    </div>


    <table class="ui celled compact single line table">
      <thead>
        <tr>
          <th>Transaction type</th>
          <th class="right aligned">Active</th>
        </tr>
      </thead>

      <tbody v-if="settings.notifications.length == 0">
        <tr>
          <td colspan="2">No notification settings yet.</td>
        </tr>
      </tbody>

      <tbody v-else>
        <tr v-for="(n, key) in settings.notifications" :key="key">
          <td>{{state.constants.trx_transaction_types.wallet.types[key]}}</td>
          <td :class="['right', 'aligned', n ? 'green' : 'red']">
            {{n ? 'Yes' : 'No'}}
          </td>
        </tr>
      </tbody>
    </table>

  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'

export default {
  name: 'notifications',

  data () {
    return {
      state: store.state,
      operators: store.state.operators.bill,
      settings: store.state.profile.settings,

      add_notification: false,
      trx_type: '',
      active: false
    }
  },

  mounted: function () {
    try {
      if ($ && $.fn && $.fn.dropdown) {
        $('select.dropdown').dropdown()
      }
      if ($ && $.fn && $.fn.checkbox) {
        $('.ui.checkbox').checkbox()
      }
    } catch (e) {
      // Semantic UI not loaded yet
    }
  },

  methods: {
    updateSettings () {
      this.settings.notifications[this.trx_type] = this.active
      this.$api.post(url_for('profile/settings/update'), this.settings).then(
        (response) => {
          this.settings = response.data
          this.state.message = { header: 'Success', class: 'success', list: ['Your notification settings are updated.'] }
          this.add_notification = false
        },
        (response) => {console.log(response.data)}
      )
    },

    setActive () {
      if (this.settings.notifications[this.trx_type]) {
        this.active = this.settings.notifications[this.trx_type]
      } else {
        this.active = false
      }
    }
  }

}
</script>