<template>
  <div>
    <div class="ui attached error message">
      <div class="header">
        Please authenticate yourself
      </div>
      <p>Enter your one-time authentication code </p>
    </div>

    <form v-show="!show_help" class="ui form attached fluid segment" autocomplete="false">
      <div class="field" :class="{ error: errors.otp }">
        <label>Authentication code</label>
        <input  type="text"
                name="code"
                placeholder="Enter authentication code"
                v-model="otp"><br>
        <div v-if="errors.otp" class="ui basic red pointing prompt label transition visible">{{errors.otp[0]}}</div>
      </div>
      <button class="ui blue submit button" :class="{disabled: state.processing}" @click.prevent="submit(otp)">
        Authenticate
      </button>

      <button class="ui basic submit button" @click.prevent="cancel()">
        Cancel
      </button>
    </form>

    <form class="ui form attached fluid segment" v-show="show_help">
      <page :slug="'authenticator'"></page>
      <div class="ui divider hidden"></div>
      <div class="ui basic button" @click="show_help = !show_help">Close</div>
    </form>

    <div class="ui bottom attached warning message">
      <i class="icon help"></i>
      No authenticator? Read more <a href @click.prevent="show_help = !show_help">here</a>.
    </div>

  </div>
</template>

<script>

import {url_for} from '../constants'
import store from '../store'
import Page from './public/page'
// import auth from '../auth'

export default {

  name: 'verify-otp',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      otp: '',
      errors: '',
      show_help: false
    }
  },

  props: ['callback', 'callback_args', 'cancel_callback'],

  components: {
    page: Page
  },

  methods: {
    submit (otp) {

      if (!otp) {
        this.errors = {otp: ['must be filled']}
        return
      }

      this.$api
        .post(url_for('verify-otp'), {otp: otp}).then(
          (response) => {
            this.state.show_otp = false
            // execute callback with proper context
            if (this.callback_args) {
              this.callback.apply(this.$parent, this.callback_args)
            } else if (this.callback) {
              this.callback.call(this.$parent)
            }
          },
          (response) => {this.errors = response.data}
        )
    },

    cancel () {
      if (this.cancel_callback) {
        this.cancel_callback.call(this.$parent)
      } else {
        this.utils.cancelAction(this.state)
      }
    }
  }

}
</script>
