<template>
  <div class="ui segment">

    <h2 class="ui dividing header">
      Pay a bill
      <div class="sub header">{{utils.showFee('bill', account, state)}}</div>
    </h2>

    <p>
      <div class="ui tiny label">NOTE</div>
      You can check your balance before paying a bill
      <a href @click.prevent="check_balance = !check_balance">here</a>.
    </p>

    <template v-if="check_balance">
      <balance-inquiry :account="account"></balance-inquiry>
    </template>

    <template v-else>
        <form class="ui form" autocomplete="false">

          <div class="three fields">
            <div class="field" :class="{ error: errors.operator_code }">
              <label>Operator</label>
              <select v-model="pay_bill.operator_code" class="ui dropdown">
                <option value="">Select operator</option>
                <option v-for="o in sortedOperators" :key="o.code" :value="o['code']">{{o['name']}}</option>
              </select><br>
              <div v-if="errors.operator_code" class="ui basic red pointing prompt label transition visible">{{errors.operator_code[0]}}</div>
            </div>

            <div class="field" :class="{ error: errors.customer_number }">
              <label>Your customer number</label>
              <input  placeholder="Enter customer number"
                      type="text"
                      v-model="pay_bill.customer_number"><br>
              <div v-if="errors.customer_number" class="ui basic red pointing prompt label transition visible">{{errors.customer_number[0]}}</div>
            </div>

            <div class="field" :class="{ error: errors.amount }">
              <label>Amount to pay</label>
              <div class="ui left labeled input">
                <div class="ui label">{{account.currency}}</div>
                <input  placeholder="Enter amount"
                        type="text"
                        v-model="pay_bill.amount"
                        maxlength="9"
                        id="currency">
              </div><br>
              <div v-if="errors.amount" class="ui basic red pointing prompt label transition visible">{{errors.amount[0]}}</div>
            </div>
          </div>

          <div v-if="!state.show_otp">
            <button class="ui blue submit button"
                    :class="{disabled: state.processing}"
                    @click.prevent="payBill()">
              Pay bill
            </button>

            <a class="ui basic button" @click="utils.cancelAction(state)">
              Cancel
            </a>
          </div>

        </form>

        <div v-if="state.show_otp">
          <br>
          <verify-otp :callback="payBill"></verify-otp>
        </div>
      </template>

  </div>
</template>

<script>

import {url_for} from '../../../constants'
import store from '../../../store'

import VerifyOtp from '../../verify_otp.vue'
import BalanceInquiry from './balance_inquiry.vue'

import _ from 'underscore'
import { validateAmount, validateCustomerNumber } from '../../../utils/validation'

export default {
  name: 'pay-bill',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      pay_bill: {operator_code: '', customer_number: ''},
      operators: store.state.operators.bill,
      check_balance: false,
      errors: ''
    }
  },

  props: ['account', 'callbacks'],

  components: {
    'verify-otp': VerifyOtp,
    'balance-inquiry': BalanceInquiry
  },

  mounted: function () {
    this.pay_bill.account_id = this.account.id
    $('select.dropdown').dropdown()
    $('#currency').maskMoney()
  },

  computed: {
    sortedOperators() {
      if (!this.operators) return []
      return [...this.operators].sort((a, b) => {
        return (a.name || '').localeCompare(b.name || '')
      })
    }
  },

  watch: {
    'pay_bill.operator_code': function () {
      this.setCustomerNumber()
    }
  },

  methods: {

    validateBillPayment () {
      // Client-side validation before submitting
      this.errors = {}
      let isValid = true

      // Validate operator selection
      if (!this.pay_bill.operator_code) {
        this.errors.operator_code = ['Please select an operator']
        isValid = false
      }

      // Validate customer number
      if (!this.pay_bill.customer_number) {
        this.errors.customer_number = ['Customer number is required']
        isValid = false
      } else {
        const customerNumberResult = validateCustomerNumber(
          this.pay_bill.customer_number,
          this.pay_bill.operator_code
        )
        if (!customerNumberResult.valid) {
          this.errors.customer_number = [customerNumberResult.error]
          isValid = false
        }
      }

      // Validate amount
      if (!this.pay_bill.amount) {
        this.errors.amount = ['Amount is required']
        isValid = false
      } else {
        const amountResult = validateAmount(this.pay_bill.amount, {
          min: 0.01,
          max: 100000
        })
        if (!amountResult.valid) {
          this.errors.amount = [amountResult.error]
          isValid = false
        }
      }

      return isValid
    },

    payBill () {
      // Validate before submitting
      if (!this.validateBillPayment()) {
        return
      }

      this.$api.post(url_for('pay-bill'), this.utils.currencyToCents(_.clone(this.pay_bill), ['amount'])
      ).then(
        (response) => {
          this.state.notification = {title: 'You payed a bill.', body: response.data}
          this.utils.cancelAction(this.state)
          for (let callback of this.callbacks) { callback() }
          this.utils.scrollToTop()
        },
        (response) => {this.errors = response.data}
      )
    },

    setCustomerNumber () {
      if (this.state.profile.settings.accounts[this.pay_bill.operator_code]) {
        this.pay_bill.customer_number = this.state.profile.settings.accounts[this.pay_bill.operator_code]
      } else {
        this.pay_bill.customer_number = ''
      }
    }
  }

}
</script>
