<template>

  <div class="ui right floated pagination menu">

    <template v-if="current_page == 1">
      <a class="icon item disabled">
        <i class="left chevron icon"></i>
      </a>
    </template>
    <template v-else>
      <a class="icon item"
        @click="current_page = current_page - 1">
        <i class="left chevron icon"></i>
      </a>
    </template>

    <template v-if="total_pages > gap_threshold">
      <template v-for="(page, index) in gap_threshold">
        <a :key="index" class="item" :class="{disabled: page + 1 == current_page}"
          @click="current_page = page + 1">
          {{page + 1}}
        </a>
      </template>
      <div class="disabled item">
         ...
       </div>
       <template v-for="(page, index) in gap_threshold">
         <a :key="index + gap_threshold" class="item" :class="{disabled: page + 1 + total_pages - gap_threshold == current_page}"
            @click="current_page = page + 1 + total_pages - gap_threshold">
           {{page + 1 + total_pages - gap_threshold}}
         </a>
       </template>
    </template>


    <template v-else>
      <template v-for="(page, index) in total_pages">
        <a :key="index" class="item" :class="{disabled: page + 1 == current_page}"
          @click="current_page = page + 1">
          {{page + 1}}
        </a>
      </template>
    </template>

    <template v-if="current_page == total_pages">
      <a class="icon item disabled">
        <i class="right chevron icon"></i>
      </a>
    </template>
    <template v-else>
      <a class="icon item"
          @click="current_page = current_page + 1">
         <i class="right chevron icon"></i>
       </a>
    </template>

  </div>
</template>

<script>

export default {
  name: 'paginator',

  props: {'total_pages': Number, 'current_page': Number, 'gap_threshold': Number}

}
</script>
