<template>
  <div>

    <verify-otp :callback="toHome" :cancel_callback="toLogin"></verify-otp>

  </div>
</template>

<script>
import store from '../store'
import VerifyOtp from './verify_otp.vue'

export default {
  name: 'authorize',

  data () {
    return {
      state: store.state
    }
  },

  components: {
    'verify-otp': VerifyOtp
  },

  methods: {
    toHome () {
      this.state.authorized_login = true
      this.$router.push('/home')
      store.state.message = { header: 'Welcome', class: 'success', list: ['You are logged in.'] }
    },

    toLogin () {
      this.$router.push('/')
    }
  }
}
</script>
