<template>
  <div>
    <div class="ui attached message">
      <div class="header">
        Activate account
      </div>
      <p>Confirm your account activation to log in</p>
    </div>

    <div class="ui attached fluid segment">
      <ul>
        <li>Name: {{user.first_name}} {{user.last_name}}</li>
        <li>Email: {{user.email}}</li>
      </ul>

      <form autocomplete="false" class="ui form">
        <div class="field">
          <input  type="hidden"
                  name="token"
                  v-model="token">
        </div>

        <div class="field" :class="{ error: errors && errors.otp }">
          <label>Enter OTP Code</label>
          <p>Open your authenticator app (Google Authenticator) and enter the 6-digit code below:</p>
          <input  placeholder="Enter 6-digit OTP code"
                  type="text"
                  maxlength="6"
                  v-model="otp"
                  @input="validateOtp">
          <div v-if="errors && errors.otp" class="ui basic red pointing prompt label transition visible">
            {{errors.otp[0]}}
          </div>
        </div>

        <button class="ui blue submit button" :class="{disabled: state.processing || !isOtpValid}" @click.prevent="submit()">
          Activate account
        </button>
      </form>
    </div>

    <div class="ui bottom attached warning message">
      <i class="icon help"></i>
      No account? <router-link to="/signup">Sign up here</router-link> instead.
    </div>

  </div>
</template>

<script>

import {url_for} from '../../constants'
import auth from '../../auth'
import store from '../../store'

export default {

  name: 'activate-user',

  data () {
    return {
      state: store.state,
      token: false,
      user: false,
      otp: '',
      errors: {}
    }
  },

  created: function () {
    this.token = this.$route.params.token
    this.getUser(this.token)
  },

  computed: {
    isOtpValid () {
      return this.otp && /^\d{6}$/.test(this.otp)
    }
  },

  methods: {
    validateOtp () {
      // Ensure only numeric input
      this.otp = this.otp.replace(/\D/g, '')

      // Clear OTP error when user types
      if (this.errors && this.errors.otp) {
        this.errors.otp = null
      }
    },
    getUser (token) {
      this.$api
        .get(url_for('activate-user') + '/' + token, (data) => {
          this.user = data
        })
        .catch((err) => {
          // invalid token
          this.errors = err.data
          this.state.message = { header: 'Cannot activate account', class: 'error', list: ['Token is invalid'] }
          this.$router.push('/login')
        })
    },

    submit () {
      // Validate OTP before submitting
      if (!this.isOtpValid) {
        this.errors.otp = ['Please enter a valid 6-digit OTP code']
        return
      }

      this.$api
        .post(url_for('activate-user') + '/' + this.token, {token: this.token, otp: this.otp}, (data) => {
          console.log('Activation success, data received:', data)
          try {
            auth.storeLoginResponse(this, data)
            console.log('storeLoginResponse completed successfully')
            this.state.message = { header: 'Welcome', class: 'success', list: ['Your account is activated'] }
            console.log('About to redirect to /home')
            this.$router.push('/home')
            console.log('Redirect called')
          } catch (error) {
            console.error('Error in activation success handler:', error)
          }
        }).catch((err) => {
          console.error('Activation error:', err)
          this.errors = err.data
        })
    }
  }

}
</script>