<template>
  <div class="ui segment">

    <h2 class="ui dividing header">
      Terminals
    </h2>

    <p v-if="terminals.length == 0">
      No registered terminals.<br><br>
    </p>

    <table v-else class="ui very basic table">
      <thead>
        <tr>
          <th>#Id</th>
          <th>Merchant name</th>
          <th>Merchant phone</th>
          <th>Currency</th>
          <th>Last update</th>
          <th>Actions</th>
        </tr>
      </thead>

      <tbody>
        <template v-for="(t, index) in terminals">
          <tr :key="t.id" :class="{'disabled': state.sub_id && state.sub_id != t.id}">
            <td>{{t.id}}</td>
            <td>{{t.merchant_name}}</td>
            <td>{{t.merchant_phone}}</td>
            <td>{{t.default_currency}}</td>
            <td>{{t.updated_at | displayDate}}</td>
            <td>
              <a class="ui small basic button" @click.prevent="utils.toggleSubAction(state, 'details', t)">
                <i class="list icon"></i>
                Details
              </a>
              <a class="ui small basic button" @click.prevent="utils.toggleSubAction(state, 'cashiers', t)">
                <i class="users icon"></i>
                Cashiers
              </a>

              <div class="ui blue compact pointing dropdown top right small basic icon button hide">
                <i class="settings icon"></i>
                <div class="text">Actions</div>
                <div class="menu">
                  <a class="item" @click.prevent="utils.showSubAction(state, 'details', t)">
                    <i class="list icon"></i>
                    Details
                  </a>
                  <a class="item" @click.prevent="utils.showSubAction(state, 'cashiers', t)">
                    <i class="users icon"></i>
                    Cashiers
                  </a>

                  <div class="divider"></div>

                  <a class="item" @click.prevent="utils.showSubAction(state, 'edit', t)">
                    <i class="edit icon"></i>
                    Edit
                  </a>
                  <a class="item" @click.prevent="utils.showSubAction(state, 'changes', t)">
                    <i class="history icon"></i>
                    Changes
                  </a>
                </div>
              </div>
            </td>
          </tr>

          <tr v-if="state.sub_id == t.id">
            <td colspan="6">
              <div v-if="state.sub_action == 'cashiers'">
                <cashiers :terminal="t"></cashiers>
              </div>

              <div v-if="state.sub_action == 'create_cashier'">
                 <create-cashier :terminal="t"></create-cashier>
              </div>

              <div v-if="state.sub_action == 'edit'">
                <update :terminal.sync="t"></update>
              </div>

              <div v-if="state.sub_action == 'details'">
                <details :terminal="t"></details>
              </div>

              <div v-if="state.sub_action == 'changes'" class="ui basic segment">
                <changes  title="Terminal changes"
                          :path="['terminals', state.sub_id, 'changes'].join('/')"></changes>
              </div>
            </td>
          </tr>
        </template>
      </tbody>
    </table>

    <a class="ui basic button hide"
            @click="utils.cancelAction(state)">
      Close
    </a>
  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'
import Changes from '../shared/changes.vue'
import Details from './details.vue'
import Update from './update.vue'
import Cashiers from './cashiers.vue'
import CreateCashier from './create_cashier.vue'

export default {
  name: 'terminals',

  data () {
    return {
      state: store.state,
      utils: store.utils,
      terminals: []
    }
  },

  props: ['account_id'],

  created: function () {
    this.getTerminals()
  },

  components: {
    details: Details,
    changes: Changes,
    update: Update,
    cashiers: Cashiers,
    'create-cashier': CreateCashier
  },

  methods: {
    getTerminals () {
      this.$api.get(url_for('accounts', this.account_id, 'terminals')).then(
        (response) => {
          this.terminals = response.data
          this.$nextTick(() => {
            try {
              if ($ && $.fn && $.fn.dropdown) {
                $('.ui.dropdown').dropdown()
              }
            } catch (e) {
              // Semantic UI not loaded yet
            }
          })
        },
        (response) => {console.log(response.data)}
      )
    }
  }
}
</script>
