<template>
  <div>
    <h1>Extend session</h1>

    <div class="ui attached message">
      <div class="header">
        Your session is about to expire!
      </div>
      <p>Fill in your credentials to extend your session</p>
    </div>

    <form class="ui form attached fluid segment" autocomplete="false">
      <div class="field">
        <label>Email</label>
        <input  type="text"
                name="email"
                placeholder="Enter your email"
                v-model="credentials.email">
      </div>
      <div class="field">
        <label>password</label>
        <input  type="password"
                name="password"
                placeholder="Enter your password"
                v-model="credentials.password">
      </div>
      <button class="ui blue submit button" @click.prevent="submit()">Extend session</button>
    </form>

  </div>
</template>

<script>
import auth from '../auth'

export default {
  name: 'extend-session',

  data () {
    return {
      credentials: {
        email: '',
        password: ''
      }
    }
  },

  methods: {

    submit () {
      var credentials = {
        email: this.credentials.email,
        password: this.credentials.password
      }
      auth.login(this, credentials, { header: 'Session extended', class: 'success', list: [] })
    }
  }

}
</script>