<template>
  <div class="ui segment">

    <h2 class="ui dividing header">
      Buy a voucher
      <div v-if="operator.code === 'pa'" class="sub header">{{utils.showFee('prepaid', account, state)}}</div>
      <div v-else class="sub header">{{utils.showFee('voucher', account, state)}}</div>
    </h2>

    <form class="ui form" autocomplete="false">

      <div class="two fields">
        <div class="field" :class="{ error: errors.operator_code }">
          <label>Select operator</label>
          <select v-model="operator.code" class="ui dropdown">
            <option value="">Select operator</option>
            <option v-for="o in sortedOperators" :value="o['code']" :key="o.code">{{o['name']}}</option>
          </select><br>
          <div v-if="errors.operator_code" class="ui basic red pointing prompt label transition visible">{{errors.operator_code[0]}}</div>
        </div>

        <div v-show="vouchers.length > 0" class="field" :class="{ error: errors.name }">
          <label>Select voucher</label>
          <select v-model="buy_voucher.name" class="ui dropdown vouchers">
            <option value="">Select voucher</option>
            <option v-for="v in sortedVouchers" :value="v['name']" :key="v.name">{{v['name']}}</option>
          </select><br>
          <div v-if="errors.name" class="ui basic red pointing prompt label transition visible">{{errors.name[0]}}</div>
        </div>
      </div>

      <div v-show="operator.code && vouchers.length == 0" class="two fields">
        <div class="field" :class="{ error: errors.amount }">
          <label>Amount to pay</label>
          <div class="ui left labeled input">
            <div class="ui label">{{account.currency}}</div>
            <input  placeholder="Enter amount"
                    type="text"
                    v-model="buy_prepaid.amount"
                    maxlength="9"
                    id="currency">
          </div><br>
          <div v-if="errors.amount" class="ui basic red pointing prompt label transition visible">{{errors.amount[0]}}</div>
        </div>

        <div class="field" :class="{ error: errors.customer_number }">
          <label>Your meter number</label>
          <input  placeholder="Enter meter number"
                  type="text"
                  v-model="buy_prepaid.customer_number"><br>
          <div v-if="errors.customer_number" class="ui basic red pointing prompt label transition visible">{{errors.customer_number[0]}}</div>
        </div>
      </div>

      <button v-if="!state.show_otp && (buy_voucher.name || (buy_prepaid.customer_number && buy_prepaid.amount))"
              class="ui blue submit button"
              :class="{disabled: state.processing}"
              @click.prevent="buyVoucher(api_url, model)">
        Buy voucher
      </button>

      <a class="ui basic button" @click="account = utils.cancelAction(state)">
        Cancel
      </a>

    </form>

    <div v-if="state.show_otp">
      <br>
      <verify-otp :callback="buyVoucher" :callback_args="[api_url, model]"></verify-otp>
    </div>
  </div>
</template>

<script>

import {url_for} from '../../../constants'
import store from '../../../store'

import VerifyOtp from '../../verify_otp.vue'

export default {
  name: 'buy-voucher',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      operator: {code: ''},
      api_url: '',
      model: {},

      // voucher
      buy_voucher: {},
      operators: [],
      vouchers: [],

      // prepaid
      buy_prepaid: {},

      errors: '',
      voucher_value: ''
    }
  },

  props: ['account', 'callbacks'],

  components: {
    'verify-otp': VerifyOtp
  },

  created: function () {
    // merge prepaid with voucher operators
    this.operators = store.state.operators.voucher.concat(store.state.operators.prepaid)
  },

  mounted: function () {
    this.buy_voucher.account_id = this.account.id
    this.buy_prepaid.account_id = this.account.id
    $('select.dropdown').dropdown()
  },

  computed: {
    sortedOperators() {
      if (!this.operators) return []
      return [...this.operators].sort((a, b) => {
        return (a.name || '').localeCompare(b.name || '')
      })
    },
    sortedVouchers() {
      if (!this.vouchers) return []
      return [...this.vouchers].sort((a, b) => {
        return (a.name || '').localeCompare(b.name || '')
      })
    }
  },

  // select API url and data model to be sent; reset previous model
  watch: {
    'operator.code': function () {
      if (this.operator.code === 'pa') {
        this.vouchers = []
        this.api_url = 'buy-prepaid'
        this.buy_prepaid.operator_code = this.operator.code
        this.model = this.buy_prepaid
        $('#currency').maskMoney()
      } else {
        this.getVouchers()
        this.api_url = 'buy-voucher'
        this.model = this.buy_voucher
        $('.vouchers').dropdown('set text', 'Select voucher')
        $('.vouchers').dropdown('set value', '')
      }
    }
  },

  methods: {

    getVouchers () {
      this.$api.get(url_for('vouchers', this.operator.code)).then(
        (response) => {this.vouchers = response.data},
        (response) => {console.log(response.data)}
      )
    },

    buyVoucher (api_url, model) {
      this.$api.post(url_for(api_url), this.utils.currencyToCents(this.utils._.clone(this.model), ['amount'])).then(
        (response) => {
          this.state.notification = {title: 'You bought a voucher.', body: response.data}
          this.utils.cancelAction(this.state)
          for (let callback of this.callbacks) { callback() }
          this.utils.scrollToTop()
        },
        (response) => {this.errors = response.data}
      )
    }
  }

}
</script>
