/*eslint no-extend-native: 0*/
String.prototype.capitalize = function () {
  return this.charAt(0).toUpperCase() + this.slice(1)
}

import _ from 'underscore'
import {router} from './index'
import Vue from 'vue'

export default {

  // global app state
  state: {

    // session
    token: false,             // bearer token
    authenticated: false,     // logged in?
    extended_session: false,  // ask to re-authenticate
    authorized_login: false,  // login authorization

    // tfa
    show_otp: false,    // toggle tfa form and submit buttons

    // ajax processing
    processing: false,  // disabling submit button

    // cache
    profile: false, // user
    pages: {},      // pages
    products: {},   // products (vouchers)
    fees: [],
    operators: {    // operators
      bill: [],
      voucher: [],
      prepaid: [],
      by_code: {}
    },

    // accounts
    current_account_index: 0,

    // message alerts
    message: false,
    notification: false,

    // messages
    inbox: true,
    outbox: false,

    // current record(s) and action(s)
    id: false,
    action: false,
    sub_id: false,
    sub_action: false,
    sub_sub_id: false,
    sub_sub_action: false,

    // current search
    search: {
      transaction: {active: false, q: {}, info: {}},
      message: {active: false, q: {sender: 'admin'}, info: {}},
      services_lodgment: {active: false, q: {}, info: {}}
    },

    addFilter (model, key, value, info) {
      this.search[model].q[key] = value
      this.search[model].info[key] = info
    },

    doSearch (route, current_page, callback) {
      if (current_page === 1) {
        callback()
      } else {
        router.push('/' + route + '/1')
      }
    },

    cancelSearch (model, callback, filter) {
      this.id = false
      this.search[model].q = {}
      this.search[model].info = {}
      if (callback) { // reset search
        // add extra filter if any
        if (filter) {this.search[model].q = filter}
        try {
          if ($ && $('#search')[0]) {
            $('#search')[0].reset()
          }
          if ($ && $.fn && $.fn.dropdown) {
            $('form .dropdown').dropdown('clear')
          }
        } catch (e) {
          // jQuery or Semantic UI not loaded
        }
        callback()
        return
      }
      this.search[model].active = false
    },

    // multiple by 100 to get cents and strip non truthy keys
    searchParams (model, filter) {

      // fix amounts
      // 12, 12.3, 12.34, 12.345 => 1234
      var massaged_search_params = _.mapObject(this.search[model].q, function (val, key) {
        if (key.indexOf('amount') > -1 || key.indexOf('balance') > -1) {
          return Math.floor(val * 100)
        } else {
          return val
        }
      })

      // strip non truthy keys
      var compact_search_params = _.pick(massaged_search_params, _.identity)

      // add extra filter if any
      if (filter) {_.extend(compact_search_params, filter)}

      // return final search object
      return Object.keys(compact_search_params).length === 0 ? {} : {search: compact_search_params}
    }
  },

  // utility functions
  utils: {

    showFee: function showFee (trx_type, account, state) {
      var fee = state.fees.find(function (fee) {
        return fee.transaction_type === trx_type && fee.user_type === state.profile.type &&
        fee.account_type === account.type && fee.currency === account.currency
      })
      if (fee) return 'Transaction fee: ' + fee.amount / 100 + ' ' + fee.currency
    },

    timeStamp: function timeStamp (stamp) {
      // stamp: "2016-04-25 10:31:39 +0200"
      if (stamp) {
        return stamp.slice(0, 19)
      } else {
        return 'Not set'
      }
    },

    humanize: function humanize (value) {
      if (!value) {return ''}
      return value.replace(/_id$/, '').replace(/_/g, ' ').trim().capitalize()
    },

    // capitalize each fragment delimited by space or by optional _
    titleize: function titleize (value, chr) {
      var regex
      if (chr === '_') {
        regex = /(?:^|_|-)\S/g
      } else {
        regex = /(?:^|\s|-)\S/g
      }
      return value.toLowerCase().replace(regex, function (c) {
        return c.toUpperCase()
      })
    },

    modulize: function modulize (value) {
      return value.replace(/_/g, '/')
    },

    showAction: function showAction (state, action, object, type) {
      if (state.action === action) { // toggle
        state.action = false
        state.id = false
        return
      }
      if (object) {
        state.original = _.clone(object)
        state.id = object.id
      }
      state.action = action
      state.type = type
      state.show_otp = false
      Vue.nextTick(function () {
        try {
          if ($ && $.fn && $.fn.velocity && $('.scroll-to-me').length) {
            $('.scroll-to-me').velocity('scroll', { offset: '0px', duration: 100, mobileHA: false })
          }
        } catch (e) {
          // jQuery Velocity not loaded
        }
      })
    },

    toggleAction: function toggleAction (state, action, object, type) {
      if (state.action === action) {
        return this.cancelAction(state, false)
      } else {
        this.showAction(state, action, object, type)
      }
    },

    cancelAction: function cancelAction (state, reset = true) {
      state.show_otp = false
      // if (reset && (state.id || state.sub_id)) { $('.ui.dropdown').dropdown('set text', 'Action') }
      if (state.sub_sub_id) {
        state.sub_sub_id = false
        state.sub_sub_action = false
        return state.sub_sub_original
      }
      if (state.sub_id) {
        state.sub_id = false
        state.sub_action = false
        return state.sub_original
      }
      state.id = false
      state.action = false
      return state.original
    },

    showSubAction: function showAction (state, action, object) {
      if (object) {
        state.sub_original = _.clone(object)
        state.sub_id = object.id
      }
      state.sub_action = action
      state.show_otp = false
    },

    toggleSubAction: function toggleSubAction (state, action, object) {
      if (state.sub_action === action) {
        return this.cancelAction(state, false)
      } else {
        this.showSubAction(state, action, object)
      }
    },

    showSubSubAction: function showAction (state, action, object) {
      if (object) {
        state.sub_sub_original = _.clone(object)
        state.sub_sub_id = object.id
      }
      state.sub_sub_action = action
      state.show_otp = false
    },

    comingSoon: function comingSoon (state) {
      state.message = { header: 'Coming soon', class: 'info', list: [] }
    },

    // hack - calendar doesnt trigger model update
    setKeyFromInputValue (object, key, e) {
      try {
        if ($ && e && e.target) {
          Vue.set(object, key, $(e.target).val())
        } else if (e && e.target) {
          Vue.set(object, key, e.target.value)
        }
      } catch (err) {
        // jQuery not loaded, fallback to native value
        if (e && e.target) {
          Vue.set(object, key, e.target.value)
        }
      }
    },

    // 1,234.56 to 123456
    currencyToCents (object, attrs) {
      for (let attr of attrs) {
        if (object[attr]) {object[attr] = Math.floor(object[attr].toString().replace(',', '') * 100)}
      }
      return object
    },

    // (-123456, USD ) to -1,234.56 USD
    toCurrency (value_in_cents, currency) {
      var value = value_in_cents / 100
      var decimals
      const digitsRE = /(\d{3})(?=\d)/g

      value = parseFloat(value)
      if (!isFinite(value) || (!value && value !== 0)) return ''
      // currency = currency != null ? currency : '$'
      decimals = decimals != null ? decimals : 2
      var stringified = Math.abs(value).toFixed(decimals)
      var _int = decimals
        ? stringified.slice(0, -1 - decimals)
        : stringified
      var i = _int.length % 3
      var head = i > 0
        ? (_int.slice(0, i) + (_int.length > 3 ? ',' : ''))
        : ''
      var _float = decimals
        ? stringified.slice(-1 - decimals)
        : ''
      var sign = value < 0 ? '-' : ''
      var number_part = sign + head + _int.slice(i).replace(digitsRE, '$1,') + _float
      if (currency) {
        return number_part + ' ' + currency
      } else {
        return number_part
      }
    },

    sumArray (arr, attr) {
      var sum = 0
      for (let item of arr) {
        if (attr) {
          sum = sum + item[attr]
        } else {
          sum = sum + item
        }
      }
      return sum
    },

    // maps operators/product to db records for lodgments
    findItemByKeyAndValue (arr, key, value) {
      return _.find(arr, function (o) {return o[key] === value})
    },

    scrollToTop () {
      try {
        if ($ && $.fn && $.fn.velocity) {
          $('html').velocity('scroll', { offset: '0px', duration: 100, mobileHA: false })
        } else {
          window.scrollTo(0, 0)
        }
      } catch (e) {
        // jQuery Velocity not loaded, fallback to native scroll
        window.scrollTo(0, 0)
      }
    },

    // underscore as utils._
    _: _

  }
}
