/**
 * Error Handler Utility
 *
 * Provides user-friendly error messages and centralized error handling.
 * Converts technical HTTP errors into human-readable messages.
 *
 * TASK 5: Proper Error Handling
 */

/**
 * HTTP Status Code to User-Friendly Message Mapping
 */
const ERROR_MESSAGES = {
  // Client Errors (4xx)
  400: {
    title: 'Invalid Request',
    body: 'The information you provided is invalid. Please check and try again.'
  },
  401: {
    title: 'Session Expired',
    body: 'Your session has expired. Please log in to continue.'
  },
  403: {
    title: 'Access Denied',
    body: 'You don\'t have permission to perform this action.'
  },
  404: {
    title: 'Not Found',
    body: 'The requested resource was not found.'
  },
  409: {
    title: 'Conflict',
    body: 'This action conflicts with existing data. Please refresh and try again.'
  },
  422: {
    title: 'Validation Error',
    body: 'Please check your input and try again.'
  },
  429: {
    title: 'Too Many Requests',
    body: 'You\'re making requests too quickly. Please wait a moment and try again.'
  },

  // Server Errors (5xx)
  500: {
    title: 'Server Error',
    body: 'Something went wrong on our end. Please try again later.'
  },
  502: {
    title: 'Service Unavailable',
    body: 'The service is temporarily unavailable. Please try again in a few moments.'
  },
  503: {
    title: 'Service Unavailable',
    body: 'The service is currently undergoing maintenance. Please try again later.'
  },
  504: {
    title: 'Request Timeout',
    body: 'The request took too long to complete. Please try again.'
  },

  // Network Errors
  0: {
    title: 'Connection Error',
    body: 'Unable to connect to the server. Please check your internet connection.'
  }
}

/**
 * Operation-specific error messages
 */
const OPERATION_MESSAGES = {
  login: {
    title: 'Login Failed',
    body: 'Invalid email or password. Please check your credentials and try again.'
  },
  signup: {
    title: 'Registration Failed',
    body: 'Unable to complete registration. Please check your information and try again.'
  },
  transfer: {
    title: 'Transfer Failed',
    body: 'Unable to complete the transfer. Please check your balance and try again.'
  },
  payment: {
    title: 'Payment Failed',
    body: 'Unable to process the payment. Please try again or contact support.'
  },
  update: {
    title: 'Update Failed',
    body: 'Unable to save your changes. Please try again.'
  },
  delete: {
    title: 'Delete Failed',
    body: 'Unable to delete the item. Please try again.'
  },
  upload: {
    title: 'Upload Failed',
    body: 'Unable to upload the file. Please check the file size and format.'
  }
}

/**
 * Get user-friendly error message from HTTP response
 *
 * @param {object} response - HTTP response object
 * @param {string} operation - Optional operation context (login, transfer, etc.)
 * @returns {object} - {title: string, body: string, list: array}
 *
 * @example
 * const error = getErrorMessage(response, 'login')
 * store.state.message = {
 *   header: error.title,
 *   class: 'error',
 *   list: error.list || [error.body]
 * }
 */
export function getErrorMessage (response, operation = null) {
  // Handle null/undefined response
  if (!response) {
    return {
      title: 'Unknown Error',
      body: 'An unexpected error occurred. Please try again.',
      list: []
    }
  }

  const status = response.status || 0
  let list = []

  // Check if server provided a custom error message
  if (response.data && response.data.message) {
    if (typeof response.data.message === 'string') {
      // Simple string message
      return {
        title: 'Error',
        body: response.data.message,
        list: []
      }
    } else if (response.data.message.title && response.data.message.body) {
      // Structured message from server
      return {
        title: response.data.message.title,
        body: response.data.message.body,
        list: response.data.message.list || []
      }
    }
  }

  // Check for validation errors (Laravel/Django style)
  if (response.data && typeof response.data === 'object') {
    // Check if it's a validation error object {field: [errors]}
    const keys = Object.keys(response.data)
    if (keys.length > 0 && Array.isArray(response.data[keys[0]])) {
      // Collect all validation errors
      list = []
      keys.forEach(field => {
        const fieldErrors = response.data[field]
        if (Array.isArray(fieldErrors)) {
          fieldErrors.forEach(error => {
            list.push(`${field.charAt(0).toUpperCase() + field.slice(1)}: ${error}`)
          })
        }
      })

      return {
        title: 'Validation Error',
        body: 'Please correct the following errors:',
        list: list
      }
    }
  }

  // Use operation-specific message if available
  if (operation && OPERATION_MESSAGES[operation]) {
    return {
      title: OPERATION_MESSAGES[operation].title,
      body: OPERATION_MESSAGES[operation].body,
      list: []
    }
  }

  // Fallback to HTTP status code message
  const errorMessage = ERROR_MESSAGES[status] || ERROR_MESSAGES[500]

  return {
    title: errorMessage.title,
    body: errorMessage.body,
    list: []
  }
}

/**
 * Format error for display in state.message
 *
 * @param {object} response - HTTP response object
 * @param {string} operation - Optional operation context
 * @returns {object} - Formatted message object for store.state.message
 *
 * @example
 * store.state.message = formatErrorForMessage(response, 'login')
 */
export function formatErrorForMessage (response, operation = null) {
  const error = getErrorMessage(response, operation)

  return {
    header: error.title,
    class: 'error',
    list: error.list.length > 0 ? error.list : [error.body]
  }
}

/**
 * Format error for notification toast
 *
 * @param {object} response - HTTP response object
 * @param {string} operation - Optional operation context
 * @returns {object} - Formatted notification object for store.state.notification
 *
 * @example
 * store.state.notification = formatErrorForNotification(response, 'transfer')
 */
export function formatErrorForNotification (response, operation = null) {
  const error = getErrorMessage(response, operation)

  return {
    title: error.title,
    body: error.list.length > 0 ? error.list.join(', ') : error.body
  }
}

/**
 * Check if error should be handled by global interceptor
 *
 * @param {number} status - HTTP status code
 * @returns {boolean} - True if interceptor should handle, false otherwise
 */
export function shouldHandleGlobally (status) {
  // These status codes are handled by the global HTTP interceptor
  return [401, 403, 500, 502, 503, 504].includes(status)
}

/**
 * Log error to console (for debugging)
 *
 * @param {object} response - HTTP response object
 * @param {string} context - Context information (component name, operation, etc.)
 */
export function logError (response, context = '') {
  if (process.env.NODE_ENV !== 'production') {
    console.group(`Error${context ? ` in ${context}` : ''}`)
    console.error('Status:', response.status)
    console.error('Data:', response.data)
    console.error('Response:', response)
    console.groupEnd()
  }
}

/**
 * Check if error is a network error (no response from server)
 *
 * @param {object} response - HTTP response object
 * @returns {boolean} - True if network error
 */
export function isNetworkError (response) {
  return !response || response.status === 0 || !response.status
}

/**
 * Check if error is a validation error (422 or field errors)
 *
 * @param {object} response - HTTP response object
 * @returns {boolean} - True if validation error
 */
export function isValidationError (response) {
  if (!response) return false

  // Check status code
  if (response.status === 422) return true

  // Check if response.data has validation error structure
  if (response.data && typeof response.data === 'object') {
    const keys = Object.keys(response.data)
    if (keys.length > 0 && Array.isArray(response.data[keys[0]])) {
      return true
    }
  }

  return false
}

/**
 * Get user-friendly message for specific HTTP status codes
 *
 * @param {number} status - HTTP status code
 * @returns {object} - {title: string, body: string}
 */
export function getStatusMessage (status) {
  return ERROR_MESSAGES[status] || ERROR_MESSAGES[500]
}

export default {
  getErrorMessage,
  formatErrorForMessage,
  formatErrorForNotification,
  shouldHandleGlobally,
  logError,
  isNetworkError,
  isValidationError,
  getStatusMessage
}
