<template>
  <div>

    <h3 class="ui dividing header">Operator settings</h3>

    <a v-show="!add_account" class="ui basic button" @click="add_account = !add_account">
      Add/edit accounts
    </a>

    <div v-show="add_account" class="ui segment">

      <h4 class="ui dividing header">Add or edit account for operator</h4>

      <form class="ui form" autocomplete="false">
        <div class="two fields">
          <div class="field">
            <label>Operator</label>
            <select v-model="operator_code" class="ui fluid dropdown" @change="setAccountNumber()">
              <option value="">Select operator</option>
              <option v-for="o in sortedOperators" :key="o.code" :value="o['code']">{{o['name']}}</option>
            </select><br>
          </div>

          <div class="field">
            <label>Account number</label>
            <input  placeholder="Enter account number"
                    type="text"
                    v-model="account_number"><br>
          </div>
        </div>

        <p>
          <a class="ui blue submit button"
                  :class="{disabled: state.processing}"
                  @click="updateSettings()">
            Add/edit operator setting
          </a>

          <a class="ui basic button" @click="add_account = !add_account">
            Cancel
          </a>
        </p>

      </form>
    </div>


    <table class="ui celled compact single line table">
      <thead>
        <tr>
          <th>Operator</th>
          <th class="right aligned">Account number</th>
        </tr>
      </thead>

      <tbody v-if="settings.accounts.length == 0">
        <tr>
          <td colspan="2">No operator settings yet.</td>
        </tr>
      </tbody>

      <tbody v-else>
        <tr v-for="(a, operatorCode) in settings.accounts" :key="operatorCode">
          <td>{{state.operators.by_code[operatorCode]}}</td>
          <td class="right aligned">{{a}}</td>
        </tr>
      </tbody>
    </table>

  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'

export default {
  name: 'accounts',

  data () {
    return {
      state: store.state,
      operators: store.state.operators.bill,
      settings: store.state.profile.settings,

      add_account: false,
      operator_code: '',
      account_number: ''
    }
  },

  mounted: function () {
    try {
      if ($ && $.fn && $.fn.dropdown) {
        $('select.dropdown').dropdown()
      }
    } catch (e) {
      // Semantic UI not loaded yet
    }
  },

  computed: {
    sortedOperators() {
      if (!this.operators) return []
      return [...this.operators].sort((a, b) => {
        return (a.name || '').localeCompare(b.name || '')
      })
    }
  },

  methods: {
    updateSettings () {
      this.settings.accounts[this.operator_code] = this.account_number
      this.$api.post(url_for('profile/settings/update'), this.settings).then(
        (response) => {
          this.settings = response.data
          this.state.message = { header: 'Success', class: 'success', list: ['Your operator settings are updated.'] }
          this.add_account = false
        },
        (response) => {console.log(response.data)}
      )
    },

    setAccountNumber () {
      if (this.settings.accounts[this.operator_code]) {
        this.account_number = this.settings.accounts[this.operator_code]
      } else {
        this.account_number = ''
      }
    }
  }

}
</script>