<template>
  <div class="ui segment">
    <h2 class="ui dividing header">
      Transfer funds from my bank account to this account
      <div class="sub header">{{utils.showFee('transfer_bank_to_wallet', account, state)}}</div>
    </h2>

    <form class="ui form" autocomplete="false">

      <div class="two fields">

        <div class="field" :class="{ error: errors.source_account_id }">
          <label>Bank account</label>
          <select v-model="transfer.source_account_id" class="ui fluid dropdown">
            <option value="">Select</option>
            <option v-for="a in bank_accounts" :value="a.id" :key="v-for="a in bank_accounts".id">{{state.constants.account_types[a.type]}}: #{{a.account_number}}</option>
          </select>
          <div v-if="errors.source_account_id" class="ui basic red pointing prompt label transition visible">{{errors.source_account_id[0]}}</div>
        </div>

        <div class="field" :class="{ error: errors.amount }">
          <label>Amount</label>

          <div class="ui left labeled input">
            <div class="ui label">{{account.currency}}</div>
            <input  placeholder="Enter amount"
                    type="text"
                    v-model="transfer.amount"
                    maxlength="9"
                    id="currency">
          </div><br>
          <div v-if="errors.amount" class="ui basic red pointing prompt label transition visible">{{errors.amount[0]}}</div>
        </div>
      </div>

      <div class="field" :class="{ error: errors.note }">
        <label>Transfer note</label>
        <input  placeholder="Enter transfer note"
                type="text"
                v-model="transfer.note"><br>
        <div v-if="errors.note" class="ui basic red pointing prompt label transition visible">{{errors.note[0]}}</div>
      </div>

      <div v-if="!state.show_otp">
        <button class="ui blue submit button"
                :class="{disabled: state.processing}"
                @click.prevent="transferFunds()">
          Transfer
        </button>

        <a class="ui basic button" @click="utils.showAction(state, 'select-transfer', account)">
          Cancel
        </a>
      </div>

    </form>

    <div v-if="state.show_otp">
      <br>
      <verify-otp :callback="transferFunds"></verify-otp>
    </div>

  </div>
</template>

<script>

import {url_for} from '../../../constants'
import store from '../../../store'

import VerifyOtp from '../../verify_otp.vue'

import _ from 'underscore'

export default {
  name: 'transfer-from-bank',

  data () {
    return {
      state: store.state,
      utils: store.utils,

      transfer: {},
      errors: ''
    }
  },

  props: ['account', 'callbacks', 'bank_accounts'],

  components: {
    'verify-otp': VerifyOtp
  },

  mounted: function () {
    $('.ui.dropdown').dropdown()
    $('#currency').maskMoney()
    this.transfer.currency = this.account.currency
    this.transfer.target_account_id = this.account.id
  },

  methods: {
    transferFunds () {

      this.$api.post(url_for('transfer/bank-to-wallet'), this.utils.currencyToCents(_.clone(this.transfer), ['amount'])).then(
        (response) => {

          var source_account_id = this.transfer.source_account_id
          var source_account = this.utils._.find(this.bank_accounts, function (a) {return (a.id === source_account_id)})
          this.state.notification = {title: 'Funds are transferred from ' + source_account.type + ' account #' + source_account.account_number + '.'}

          this.utils.cancelAction(this.state)
          for (let callback of this.callbacks) { callback() }
          this.utils.scrollToTop()
        },
        (response) => {
          if (response.data.status === 'declined') {
            this.errors = ''
            this.state.notification = {title: response.data.response_message,
                                       class: 'error', body: {'Response code': response.data.response_code}}
          } else {
            this.errors = response.data
          }
        }
      )
    }

  }

}
</script>
