<template>
  <div>

    <h2 class="ui dividing header">
      <div class="content">
        Messages - {{state.inbox ? 'Inbox' : 'Outbox'}}
        <div class="sub header">Send and receive messages | Total found: {{count}}</div>
      </div>
    </h2>

    <p>
      <a class="ui basic button" @click="getMessages()">
        <i class="refresh icon"></i> Refresh data
      </a>
      <a v-if="state.inbox" class="ui basic small button" @click="switchBox('outbox')">
        <i class="inbox icon"></i>
        Show outbox
      </a>
      <a v-if="state.outbox" class="ui basic small button" @click="switchBox('inbox')">
        <i class="inbox icon"></i>
        Show inbox
      </a>
    </p>

    <i id="arrow" v-show="attr" :class="direction == -1 ? 'down' : 'up'" class="angle icon"></i>

    <table class="ui celled compact single line selectable table">
      <thead>
        <tr :class="{'disabled': state.id, 'pointer': !state.id }">
          <th @click="reorder('id', $event)">#Id</th>
          <th @click="reorder('title', $event)">Title</th>
          <th v-if="state.inbox" class="right aligned" @click="reorder('read_by_user', $event)">Read</th>
          <th @click="reorder('created_at', $event)">{{ state.inbox ? 'Received at' : 'Sent at'}}</th>
        </tr>
      </thead>

      <tbody v-if="messages.length == 0">
        <tr>
          <td colspan="4">
            No records.
          </td>
        </tr>
      </tbody>

      <tbody v-else class="pointer">
        <template v-for="(message, index) in sortedMessages">
          <tr :key="message.id" :class="{'disabled': state.id && state.id != message.id}"
              @click.prevent="utils.toggleAction(state, 'details', message)">
            <td :class="{'scroll-to-me': state.id == message.id}">{{message.id}}</td>
            <td>{{message.title}}</td>
            <td v-if="state.inbox" :class="['right', 'aligned', message.read_by_user ? 'green' : 'red']">
               {{message.read_by_user ? 'Yes' : 'No'}}
            </td>
            <td>{{message.created_at | displayDate}}</td>
          </tr>

          <tr class="no-pointer no-hover" v-if="state.id == message.id">
            <td colspan="4">
              <details :message="message"></details>
            </td>
          </tr>
        </template>
      </tbody>

      <tfoot v-if="total_pages > 1">
        <tr>
          <th colspan="4">
            <paginator :route="'messages'" :total_pages="total_pages"
                       :current_page="current_page" :gap_treshold="gap_treshold"></paginator>
          </th>
        </tr>
      </tfoot>
    </table>

  </div>
</template>

<script>
import {url_for} from '../../constants'
import store from '../../store'
import Paginator from './../shared/paginator.vue'
import Details from './details.vue'

export default {
  name: 'messages',

  data () {
    return {
      state: store.state,
      utils: store.utils,

      messages: [],

      count: 0,
      gap_treshold: 5,
      per_page: null,
      total_pages: null, // this will be computed from response when mounted

      // ordering
      attr: false,
      direction: -1
    }
  },

  components: {
    paginator: Paginator,
    details: Details
  },

  route: {
    canReuse: false
  },

  created: function () {
    this.current_page = parseInt(this.$route.params.page, 10) || 1
    this.getMessages()
  },

  computed: {
    sortedMessages() {
      if (!this.messages || !this.attr) return this.messages
      return [...this.messages].sort((a, b) => {
        let aVal = a[this.attr]
        let bVal = b[this.attr]
        if (aVal < bVal) return -1 * this.direction
        if (aVal > bVal) return 1 * this.direction
        return 0
      })
    }
  },

  methods: {
    getMessages () {
      this.$api.post(url_for('messages', this.current_page), this.state.searchParams('message')).then(
        (response) => {
          this.count = response.headers['x-total-count']
          this.per_page = response.headers['x-per-page']
          this.messages = response.data
          this.total_pages = Math.ceil(this.count / this.per_page)
        },
        (response) => {console.log(response.data)}
      )
    },

    switchBox (box) {
      if (box === 'inbox') {
        this.state.inbox = true
        this.state.outbox = false
        this.state.search.message.q = {sender: 'admin'}
      } else if (box === 'outbox') {
        this.state.inbox = false
        this.state.outbox = true
        this.state.search.message.q = {sender: 'user'}
      }
      if (this.$route.params.page === '1') {
        this.getMessages() // route doesnt change so we must reload messages
      } else {
        this.$router.push('/messages/1')
      }
    },

    reorder (attr, e) {
      this.attr = attr
      this.direction = this.direction * -1
      $(e.target).append($('#arrow'))
    }
  }

}
</script>