<template>
  <div>
    <div class="ui stackable attached menu">
      <div class="ui container">

        <template v-if="state.authenticated && state.authorized_login">
          <router-link to="/home" active-class="active">
            <i class="home icon"></i> Home
          </router-link>
          <a class="item"
              :to="{ name: 'transactions', params: {page: 1}, activeClass: 'active' }"
              @click="state.search.transaction.q = {}">
            <i class="list layout icon"></i> Transactions
          </a>
          <router-link to="/messages/1" active-class="active">
            <i class="mail icon"></i> Messages
          </router-link>
          <router-link to="/profile" active-class="active">
            <i class="user icon"></i> Profile
          </router-link>
          <a class="item" @click="logout()">
            <i class="sign out icon"></i> Logout
          </a>
        </template>

        <template v-else>
          <router-link to="/" active-class="active" exact>
            <i class="home icon"></i> Home
          </router-link>
          <router-link :to="{ name: 'about' }" active-class="active">
            <i class="question icon"></i> About
          </router-link>
          <router-link :to="{ name: 'terms' }" active-class="active">
            <i class="info icon"></i> Terms
          </router-link>
          <router-link to="/signup" active-class="active">
            <i class="add user icon"></i> Sign up
          </router-link>
          <router-link to="/login" active-class="active">
            <i class="sign in icon"></i> Login
          </router-link>
        </template>

      </div>
    </div>

    <div class="ui container">
      <app-message></app-message>

      <div v-show="state.notification" class="ui huge info message">
        <i class="close icon" @click="state.notification = false"></i>
        <div class="header">
          {{state.notification.title}}
        </div>
        <p v-show="state.notification.body">
          <template v-if="utils._.isObject(state.notification.body)">
            <ul>
              <li v-for="(i, key) in state.notification.body" :key="key">{{key}}: <strong>{{i}}</strong></li>
            </ul>
          </template>
          <strong v-else>{{state.notification.body}}</strong>
        </p>
      </div>
    </div>

    <div class="ui hidden divider medium"></div>

    <div class="ui container">
      <extend-session v-show="state.extended_session"></extend-session>
      <router-view v-show="!state.extended_session" class="slide" transition="slide"></router-view>
    </div>

    <div class="ui divider"></div>
    <div class="ui container">
      <p>&copy; Webteh Inc 2016</p>
    </div>

    <div class="ui divider hidden"></div>

  </div>
</template>

<script>

import auth from '../auth'
import Message from './message.vue'
import ExtendSession from './extend_session.vue'
import store from '../store'
import {url_for} from '../constants'

export default {
  name: 'WebPay',

  data () {
    return {
      state: store.state,
      utils: store.utils
    }
  },

  // cache pages, operators and constants
  created: function () {
    this.$api.get(url_for('constants')).then(
      (response) => {

        // pages
        response.data.pages.forEach((page) => {
          this.state.pages[page.slug] = page
        })

        // vouchers
        response.data.products.forEach((product) => {
          this.state.products[product.name] = product
        })

        // fees
        this.state.fees = response.data.fees

        // operators
        response.data.operators.forEach((operator) => {
          this.state.operators.by_code[operator.code] = operator.name
          if (operator.type === 'bill') {
            this.state.operators.bill.push(operator)
          } else if (operator.type === 'voucher') {
            this.state.operators.voucher.push(operator)
          } else if (operator.type === 'prepaid') {
            this.state.operators.prepaid.push(operator)
          }
        })

        // constants
        this.state.constants = response.data.constants
        this.state.transaction_types = this.state.constants.trx_transaction_types.all
      },
      (response) => {console.log(response.data)}
    )
  },

  components: {
    'app-message': Message,
    'extend-session': ExtendSession
  },

  methods: {
    logout () {
      auth.logout(this)
    }
  }
}
</script>
