<template>
  <div class="ui basic segment">

    <template v-if="state.sub_sub_action == 'update_cashier'">
      <template v-for="(c, index) in cashiers">
        <div :key="c.id" v-if="state.sub_sub_id == c.id">
          <update-cashier :terminal="t" :cashier="c"></update-cashier>
        </div>
      </template>
    </template>

    <template v-else>

      <h3 class="ui dividing header">
        <div class="content">
          Terminal #{{terminal.id}}: Cashiers
        </div>
      </h3>

      <p v-if="cashiers.length == 0">
        No registered cashiers.<br><br>
      </p>

      <div class="ui relaxed list">
        <div v-for="c in cashiers" :key="c.id" class="item">
          <button class="ui blue basic small button left floated content" @click.prevent="utils.showSubSubAction(state, 'update_cashier', c)">
            Edit
          </button>
          <button class="ui blue basic small button left floated content" @click.prevent="generatePin(c)">
            Generate new PIN
          </button>

          <div class="content">
            <h4 class="ui header">
              {{c.full_name}}
              <div :class="c.active ? 'teal ' : 'red'"
                    class="ui small horizontal label">
                {{c.active ? 'Active' : 'Inactive'}}
              </div>
              <div class="sub header" style="font-weight: 400;">{{c.manager ? 'Manager' : 'Employee'}} | Last update: <strong>{{c.updated_at | displayDate}}</strong></div>
            </h4>
          </div>
        </div>
      </div>

      <a class="ui basic blue button" @click.prevent="utils.showSubAction(state, 'create_cashier')">
        Create new cashier
      </a>
      <a class="ui basic button" @click="utils.cancelAction(state)">
        Close
      </a>
    </template>

  </div>
</template>

<script>

import {url_for} from '../../constants'
import store from '../../store'
import UpdateCashier from './update_cashier.vue'

export default {
  name: 'cashiers',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      cashiers: [],
      errors: ''
    }
  },

  props: ['terminal'],

  components: {
    'update-cashier': UpdateCashier
  },

  created: function () {
    this.getCashiers()
  },

  methods: {
    getCashiers () {
      this.$api.get(url_for('terminals', this.state.sub_id, 'cashiers')).then(
        (response) => {this.cashiers = response.data},
        (response) => {console.log(response.data)}
      )
    },

    generatePin (cashier) {
      this.$api.post(url_for('terminals', this.state.sub_id, 'cashiers', cashier.id, 'change-pin'), {}).then(
        (response) => {
          this.state.notification = {title: 'New PIN for ' + cashier.full_name + ' is ' + response.data.pin + '.'}
          this.utils.scrollToTop()
        },
        (response) => {console.log(response.data)}
      )
    }
  }

}
</script>
