<template>
  <div>

    <h3 class="ui dividing header">Cards</h3>

    <table class="ui very basic compact table">
      <thead>
        <tr :class="{'disabled': state.id, 'pointer': !state.id }">
          <th>Card number</th>
          <th>Exp. date</th>
          <th>Cardholder name</th>
          <th>Type</th>
          <th>Active</th>
          <th>Last used at</th>
          <th>Created at</th>
          <th>Actions</th>
        </tr>
      </thead>

      <tbody v-if="cards.length == 0">
        <tr>
          <td colspan="8">
            No records.
          </td>
        </tr>
      </tbody>

      <tbody v-else class="pointer">
        <template v-for="(card, index) in cards">
          <tr :key="card.id" :class="{'disabled': state.sub_id && state.sub_id != card.id}">
            <td :class="{'scroll-to-me': state.sub_id == card.id}">{{card.masked_pan}}</td>
            <td>{{card.exp_month}}/{{card.exp_year}}</td>
            <td>{{card.first_name}} {{card.last_name}}</td>
            <td>{{card.type | capitalize}}</td>

            <td :class="card.active ? 'green' : 'red'">
              {{card.active ? 'Yes' : 'No'}}
            </td>

            <td>{{card.last_access_at | displayDate}}</td>
            <td>{{card.created_at | displayDate}}</td>

            <td v-if="state.sub_id == card.id">
              <div v-if="state.sub_action == 'change-pin'">
                <change-pin :card.sync="card"></change-pin>
              </div>
            </td>

            <td v-else>
              <a v-if="card.state == 'pending'" class="ui small basic button" @click="utils.toggleSubAction(state, 'change-pin', card)">
                <i class="unlock icon"></i>
                Set PIN to activate the card
              </a>

              <template v-else>
                <a class="ui small basic button" @click="toggleActive(card)">
                  <template v-if="card.active">
                    <i class="lock icon"></i>
                    Block card
                  </template>
                  <template v-else>
                    <i class="unlock alternate icon"></i>
                    Unblock card
                  </template>
                </a>
                <a class="ui small basic button" @click="utils.toggleSubAction(state, 'change-pin', card)">
                  <i class="unhide icon"></i>
                  Change PIN
                </a>
              </template>
            </td>

          </tr>
        </template>
      </tbody>
    </table>

  </div>
</template>

<script>
import {url_for} from '../../constants'
import store from '../../store'
import ChangePin from './change_pin.vue'

export default {
  name: 'cards',

  data () {
    return {
      state: store.state,
      utils: store.utils,
      cards: [],
      count: 0
    }
  },

  components: {
    ChangePin: ChangePin
  },

  created: function () {
    this.getCards()
  },

  methods: {
    getCards () {
      this.$api.post(url_for('cards'), {}).then(
        (response) => {
          this.cards = response.data
        },
        (response) => {console.log(response.data)}
      )
    },

    toggleActive (card) {
      this.$api.post(url_for('cards', card.id, 'toggle-active-flag'), {}).then(
        (response) => {
          this.state.message = { header: 'Success', class: 'success', list: ['Card changed.'] }
          this.getCards()
        },
        (response) => {console.log(response.data)}
      )
    }
  }

}
</script>
