<template>
  <div class="ui basic segment">
    <h3 class="ui dividing header">
      <div class="content">
        {{message.title}}

        <div class="sub header">
          {{message.sender == 'admin' ? 'Received at' : 'Sent at'}}:
          {{message.created_at | displayDate}}
        </div>
      </div>
    </h3>

    <pre>
{{message.body}}
    </pre>

    <reply v-if="state.action == 'reply'" :message="message"></reply>

    <div v-else>
      <a v-if="message.sender == 'admin'" class="ui basic blue button"
        @click.prevent="utils.showAction(state, 'reply', message)">
        <i class="send outline icon"></i>
        Reply
      </a>
      <a class="ui basic button" @click="utils.cancelAction(state)">
        Close
      </a>
    </div>

  </div>
</template>

<script>

import store from '../../store'
import Reply from './reply.vue'
import {url_for} from '../../constants'

export default {
  name: 'message-details',

  data () {
    return {
      state: store.state,
      utils: store.utils
    }
  },

  mounted: function () {
    if (this.message.sender === 'admin' && !this.message.read_by_user) {this.readMessage()}
  },

  props: ['message'],

  components: {
    reply: Reply
  },

  methods: {
    readMessage () {
      this.$api.post(url_for('messages', this.message.id, 'read'), {}).then(
        (response) => {
          this.message.read_by_user = true
          // pass
        },
        (response) => {this.errors = response.data}
      )
    }
  }

}
</script>