<template>
  <div>

    <template v-if="!embedded">
      <h2 class="ui dividing header">
        <div class="content">
          Transactions
          <div class="sub header">Manage my transactions | Total found: {{count}}</div>
        </div>
      </h2>
    </template>

    <div v-show="!state.action || state.action == 'details'">
      <a v-if="account && account.type == 'business'" class="ui basic small blue button" @click="lodgments_switch = !lodgments_switch">
        <i class="bar chart icon"></i> Lodgments
      </a>
      <a class="ui basic small blue button" :class="{'tiny': embedded}" @click="exportTrxs('xls')">
        <i class="cloud download icon"></i>Export to XLS
      </a>
      <a class="ui basic small blue button" :class="{'tiny': embedded}" @click="exportTrxs('csv')">
        <i class="cloud download icon"></i>Export to CSV
      </a>
      <a class="ui basic small button" :class="{'tiny': embedded}" @click="refreshData()">
        <i class="refresh icon"></i> Refresh data
      </a>
      <a class="ui basic small button" :class="{'tiny': embedded}" @click="search.active = !search.active">
        <i class="search icon"></i>
        Search
      </a>
    </div>

    <form id="search" v-show="search.active" class="ui form segment" autocomplete="false">

       <div class="three fields">
         <div class="field">
           <label>Debit/Credit</label>
           <select v-model="search.q.type" class="ui dropdown">
             <option value="">All</option>
             <option v-for="(type, key) in state.constants.trx_types" :value="key" :key="key">{{type}}</option>
           </select>
         </div>

         <div class="field">
           <label>Type</label>
           <div class="ui selection dropdown">
             <input type="hidden" v-model="search.q.transaction_type">
             <i class="dropdown icon"></i>
             <div class="default text">All</div>
             <div class="menu">
               <template v-for="(typeGroup, groupIndex) in state.constants.trx_transaction_types">
                 <template v-if="!utils._.isEmpty(typeGroup.types)">
                   <div :key="`header-${groupIndex}`" class="ui disabled header">{{typeGroup.name}}</div>
                   <div :key="`divider-${groupIndex}`" class="divider"></div>
                   <div class="item" v-for="(type, key) in typeGroup.types" :data-value="key" :key="key">{{type}}</div>
                 </template>
               </template>
             </div>
           </div>
         </div>

         <div class="field">
           <label>Status</label>
           <select v-model="search.q.status" class="ui dropdown">
             <option value="">All</option>
             <option v-for="(type, key) in state.constants.trx_statuses" :value="key" :key="key">{{type}}</option>
           </select>
         </div>
       </div>

       <div class="three fields">

         <div class="field">
           <label>Amount</label>
           <input  placeholder="Enter amount"
                   type="text"
                   v-model="search.q.amount"><br>
         </div>

         <div class="field">
           <label>Amount greater than</label>
           <input  placeholder="Enter amount"
                   type="text"
                   v-model="search.q.amount_gt"><br>
         </div>

         <div class="field">
           <label>Amount less than</label>
           <input  placeholder="Enter amount"
                   type="text"
                   v-model="search.q.amount_lt"><br>
         </div>
       </div>

       <div class="three fields">

         <div class="field">
           <label>Balance</label>
           <input  placeholder="Enter balance"
                   type="text"
                   v-model="search.q.balance"><br>
         </div>

         <div class="field">
           <label>Date after</label>
           <input  placeholder="Select date"
                   type="text"
                   @click="utils.setKeyFromInputValue(search.q, 'created_at_gt', $event)"
                   class="flatpickr"
                   data-maxdate="today"
                   v-model="search.q.created_at_gt"><br>
         </div>

         <div class="field">
           <label>Date before</label>
           <input  placeholder="Select date"
                   type="text"
                   @click="utils.setKeyFromInputValue(search.q, 'created_at_lt', $event)"
                   class="flatpickr"
                   data-maxdate="today"
                   v-model="search.q.created_at_lt"><br>
         </div>
       </div>

       <button class="ui blue submit button"
               :class="{disabled: state.processing}"
               @click.prevent="state.doSearch('transactions', current_page, getTransactions)">
         Search
       </button>

       <button class="ui basic clear button" @click.prevent="state.cancelSearch('transaction', getTransactions, account ? {account_id: account.id} : false)">
         Reset search
       </button>

       <a class="ui basic button" @click="state.cancelSearch('transaction')">
         Cancel
       </a>

     </form>

    <i id="arrow" v-show="attr" :class="direction == -1 ? 'down' : 'up'" class="angle icon"></i>

    <table class="ui celled compact single line selectable table">
      <thead>
        <tr :class="{'disabled': state.id, 'pointer': !state.id }">
          <th @click="reorder('id', $event)">#Id</th>
          <th @click="reorder('created_at', $event)">Time</th>
          <th @click="reorder('transaction_type', $event)">Type</th>
          <th @click="reorder('description', $event)">Description</th>
          <th @click="reorder('amount', $event)" class="right aligned">Amount</th>
        </tr>
      </thead>

      <tbody v-if="transactions.length == 0">
        <tr>
          <td colspan="8">
            No transactions.
          </td>
        </tr>
      </tbody>

      <tbody v-else class="pointer">
        <template v-for="(t, index) in sortedTransactions">
          <tr :key="t.id" :class="{'disabled': state.id && state.id != t.id}"
              @click.prevent="utils.toggleAction(state, 'details', t, 'trx')">
            <td :class="{'scroll-to-me': state.id == t.id}">{{t.id}}</td>
            <td>{{t.created_at | displayDate}}</td>
            <td>{{state.transaction_types[t.transaction_type]}}</td>
            <td>{{t.description}}</td>
            <td :class="['right', 'aligned', t.type == 'debit' ? 'red' : 'green']">
              {{t.type == 'debit' ? '-' : '+'}}
              {{t.amount/100 | currency ''}}
              {{t.currency}}
            </td>
          </tr>

          <tr class="no-pointer no-hover" v-if="state.id == t.id && state.type == 'trx'">
            <td colspan="8">
              <details :trx="t"></details>
            </td>
          </tr>
        </template>
      </tbody>

      <tfoot v-if="total_pages > 1">
        <tr>
          <th colspan="8">
            <paginator v-if="!embedded" :route="'transactions'" :total_pages="total_pages"
                       :current_page="current_page" :gap_treshold="gap_treshold"></paginator>
            <embeded-paginator v-else :total_pages="total_pages" :current_page.sync="current_page" :gap_treshold="gap_treshold"></embeded-paginator>
          </th>
        </tr>
      </tfoot>
    </table>

  </div>
</template>

<script>
import {url_for} from '../../constants'
import store from '../../store'

import Paginator from './../shared/paginator.vue'
import EmbededPaginator from './../shared/embeded_paginator.vue'

import Details from './details.vue'

// export transactions
// import CSV from 'csv.js'  // TODO: Add CSV export library
// import Downloader from 'downloadjs'  // TODO: Add download library

import flatpickr from 'flatpickr'

export default {
  name: 'transactions',

  data () {
    return {
      state: store.state,
      utils: store.utils,
      transactions: [],
      count: 0,
      gap_treshold: 5,
      per_page: null,
      total_pages: null, // this will be computed from response when mounted
      current_page: 1,

      // ordering
      attr: false,
      direction: -1,

      // search
      search: store.state.search.transaction
    }
  },

  props: ['embedded', 'account', 'refresh_callbacks', 'lodgments_switch'],

  components: {
    paginator: Paginator,
    'embeded-paginator': EmbededPaginator,
    details: Details
  },

  route: {
    canReuse: false
  },

  created: function () {
    if (this.embedded) {
      // account will load its transactions
    } else {
      // paginated with url
      this.current_page = parseInt(this.$route.params.page, 10) || 1
      this.getTransactions()
    }
  },

  mounted: function () {
    try {
      if ($ && $.fn && $.fn.dropdown) {
        $('.ui.dropdown').dropdown()
      }
    } catch (e) {
      // Semantic UI not loaded yet
    }
    flatpickr('.flatpickr')
  },

  computed: {
    sortedTransactions() {
      if (!this.transactions || !this.attr) return this.transactions
      return [...this.transactions].sort((a, b) => {
        let aVal = a[this.attr]
        let bVal = b[this.attr]
        if (aVal < bVal) return -1 * this.direction
        if (aVal > bVal) return 1 * this.direction
        return 0
      })
    }
  },

  watch: {
    current_page: function () {
      this.getTransactions()
    }
  },

  methods: {
    getTransactions () {
      this.$api.post(url_for('transactions', this.current_page), this.state.searchParams('transaction')).then(
        (response) => {
          this.count = response.headers['x-total-count']
          this.per_page = response.headers['x-per-page']
          this.transactions = response.data
          this.total_pages = Math.ceil(this.count / this.per_page)
          try {
            if ($ && $.fn && $.fn.dropdown) {
              $('.ui.dropdown').dropdown()
            }
          } catch (e) {
            // Semantic UI not loaded yet
          }
        },
        (response) => {console.log(response.data)}
      )
    },

    refreshData () {
      // account refresher will load its transactions
      if (this.refresh_callbacks) {
        for (let callback of this.refresh_callbacks) { callback() }
      } else {
        this.getTransactions()
      }
    },

    exportTrxs (type) {
      // TODO: Implement CSV export with proper library (papaparse)
      alert('CSV export feature not yet implemented')
      console.log('Export to', type, 'requested for', this.transactions.length, 'transactions')
    },

    reorder (attr, e) {
      this.attr = attr
      this.direction = this.direction * -1
      $(e.target).append($('#arrow'))
    }
  }

}
</script>
