<template>
  <div>

    <form class="ui form" autocomplete="false">

      <div class="field" :class="{ error: errors.pin }">
        <div class="ui small action input">
          <input placeholder="Enter pin" v-model="pin">
          <a class="ui blue button" @click="changePin()">Change pin</a>
          <a class="ui basic button" @click="utils.cancelAction(state)">Cancel</a>
        </div>
        <div v-if="errors.pin" class="ui basic red pointing prompt label transition visible">{{errors.pin[0]}}</div>
      </div>

    </form>

  </div>
</template>

<script>

import store from '../../store'
import {url_for} from '../../constants'

export default {
  name: 'details',

  data () {
    return {
      state: store.state,
      utils: store.utils,

      pin: '',
      errors: {}
    }
  },

  mounted: function () {

  },

  props: ['card'],

  components: {

  },

  methods: {

    changePin () {
      this.$api.post(url_for('cards', this.card.id, 'change-pin'), {pin: this.pin}).then(
        (response) => {
          this.state.message = { header: 'Success', class: 'success', list: ['PIN is set.'] }
          this.card = response.data
          this.utils.cancelAction(this.state)
        },
        (response) => {this.errors = response.data}
      )
    }
  }

}
</script>
