<template>
  <div>

    <p v-if="logins.length == 0">No previous logins found.</p>

    <template v-else>
      <h3 class="ui dividing header">Login history</h3>
      <table class="ui very basic compact table">
        <thead>
          <tr>
            <th>IP</th>
            <th>Client</th>
            <th>Client version</th>
            <th>Platform</th>
            <th>Date</th>
          </tr>
        </thead>

        <tbody>
          <tr v-for="(login, index) in logins" :key="login.id">
            <td>{{login.ip}}</td>
            <td>{{login.browser_name}}</td>
            <td>{{login.browser_version}}</td>
            <td>{{login.platform}}</td>
            <td>{{login.created_at | displayDate}}</td>
          </tr>
        </tbody>
      </table>
    </template>

  </div>
</template>

<script>

import {url_for} from '../../constants'

export default {
  name: 'logins',

  data () {
    return {
      logins: ''
    }
  },

  created: function () {
    this.getLogins()
  },

  methods: {

    getLogins () {
      if (this.logins) { return }
      this.$api.get(url_for('profile/logins')).then(
        (response) => {
          this.logins = response.data
        },
        (response) => {console.log(response.data)}
      )
    }
  }
}
</script>