import axios from 'axios'
import store from './store'
import NProgress from 'NProgress'
import auth from './auth'

// Create axios instance with default config
const api = axios.create({
  baseURL: '/', // API calls will be relative to current origin
  timeout: 30000, // 30 second timeout
  headers: {
    'Accept': 'application/json',
    'Content-Type': 'application/json',
    'Access-Control-Expose-Headers': 'X-total-count'
  }
})

// Router reference - will be set by setRouter()
let router = null

// Set router reference (called from index.js after router is created)
export function setRouter(routerInstance) {
  router = routerInstance
}

// Request interceptor
api.interceptors.request.use(
  (config) => {
    // for button disabling
    store.state.processing = true

    // loading indicator
    NProgress.start()

    // set token to all requests
    if (store.state.token) {
      config.headers.Authorization = 'Bearer ' + store.state.token
    }

    return config
  },
  (error) => {
    store.state.processing = false
    NProgress.done()
    return Promise.reject(error)
  }
)

// Response interceptor
api.interceptors.response.use(
  (response) => {
    // for button disabling
    store.state.processing = false

    // loading indicator
    NProgress.done()

    return response
  },
  (error) => {
    // for button disabling
    store.state.processing = false

    // loading indicator
    NProgress.done()

    // Handle error responses
    if (error.response) {
      const status = error.response.status

      // not authenticated via login or redirect to login if token expired
      if (status === 401) {
        if (router) {
          auth.cleanup(router.app)
          store.state.message = {
            header: 'Session Expired',
            class: 'error',
            list: ['Your session has expired. Please log in to continue.']
          }
          router.push('/login')
        }
      }
      // not authorized via tfa or too many failed logins
      else if (status === 403) {
        store.state.show_otp = true
      }
      // handle other common server errors
      else if (status === 500) {
        store.state.message = {
          header: 'Server Error',
          class: 'error',
          list: ['Something went wrong on our end. Please try again later.']
        }
      } else if (status === 502 || status === 503) {
        store.state.message = {
          header: 'Service Unavailable',
          class: 'error',
          list: ['The service is temporarily unavailable. Please try again in a few moments.']
        }
      } else if (status === 504) {
        store.state.message = {
          header: 'Request Timeout',
          class: 'error',
          list: ['The request took too long to complete. Please try again.']
        }
      }
    } else if (error.request) {
      // Network error (no response from server)
      store.state.message = {
        header: 'Connection Error',
        class: 'error',
        list: ['Unable to connect to the server. Please check your internet connection.']
      }
    }

    return Promise.reject(error)
  }
)

export default api
