<template>
  <div>
    <div>
      <h2 class="ui dividing header">
        Balance inquiry
      </h2>

      <form class="ui form" autocomplete="false">

        <div class="three fields">
          <div class="field" :class="{ error: errors.operator_code }">
            <label>Operator</label>
            <select v-model="inquiry.operator_code" class="ui dropdown">
              <option value="">Select operator</option>
              <option v-for="o in sortedOperators" :key="o.code" :value="o['code']">{{o['name']}}</option>
            </select><br>
            <div v-if="errors.operator_code" class="ui basic red pointing prompt label transition visible">{{errors.operator_code[0]}}</div>
          </div>

          <div class="field" :class="{ error: errors.customer_number }">
            <label>Your customer number</label>
            <input  placeholder="Enter customer number"
                    type="text"
                    v-model="inquiry.customer_number"><br>
            <div v-if="errors.customer_number" class="ui basic red pointing prompt label transition visible">{{errors.customer_number[0]}}</div>
          </div>
        </div>

        <div v-if="!state.show_otp">
          <button class="ui blue submit button"
                  :class="{disabled: state.processing}"
                  @click.prevent="balaceInquiry()">
            Balance inquiry
          </button>

          <a class="ui basic button" @click="utils.cancelAction(state)">
            Cancel
          </a>
        </div>

      </form>

    </div>

    <div v-if="state.show_otp">
      <br>
      <verify-otp :callback="balaceInquiry"></verify-otp>
    </div>
  </div>
</template>

<script>

import {url_for} from '../../../constants'
import store from '../../../store'

import VerifyOtp from '../../verify_otp.vue'

export default {
  name: 'balance-inquiry',

  data () {
    return {
      utils: store.utils,
      state: store.state,
      inquiry: {operator_code: '', customer_number: ''},
      operators: store.state.operators.bill,
      errors: ''
    }
  },

  props: ['account'],

  components: {
    'verify-otp': VerifyOtp
  },

  mounted: function () {
    this.inquiry.account_id = this.account.id
    $('select.dropdown').dropdown()
  },

  computed: {
    sortedOperators() {
      if (!this.operators) return []
      return [...this.operators].sort((a, b) => {
        return (a.name || '').localeCompare(b.name || '')
      })
    }
  },

  watch: {
    'inquiry.operator_code': function () {
      this.setCustomerNumber()
    }
  },

  methods: {

    balaceInquiry () {
      this.$api.post(url_for('customer-balance-inquiry'), this.inquiry).then(
        (response) => {
          this.state.notification = {
            title: response.data.balance_info,
            body: 'Last update was at ' + this.utils.timeStamp(response.data.customer.updated_at) + '.'
          }
          this.utils.cancelAction(this.state)
          this.utils.scrollToTop()
        },
        (response) => {this.errors = response.data}
      )
    },

    setCustomerNumber () {
      if (this.state.profile.settings.accounts[this.inquiry.operator_code]) {
        this.inquiry.customer_number = this.state.profile.settings.accounts[this.inquiry.operator_code]
      } else {
        this.inquiry.customer_number = ''
      }
    }
  }

}
</script>
