<template>
  <div>

    <template v-if="!$route.params.token">
      <div class="ui attached message">
        <div class="header">
          Forgotten password
        </div>
        <p>Fill in your email address to receive instructions for the next step</p>
      </div>

      <form class="ui form attached fluid segment" autocomplete="false">
        <div class="field">
          <label>Email</label>
          <input  type="text"
                  name="email"
                  placeholder="Enter your email"
                  v-model="email">
        </div>
        <button class="ui blue submit button" :class="{disabled: state.processing}" @click.prevent="sendEmail()">Send me an email</button>
      </form>

      <div class="ui bottom attached warning message">
        <i class="icon help"></i>
        No account? <router-link to="/signup">Sign up here</router-link> instead.
      </div>
    </template>

    <template v-else>
      <div class="ui attached message">
        <div class="header">
          Change password
        </div>
        <p>{{profile.first_name}} {{profile.last_name}}, please fill in your new password</p>
      </div>

      <form class="ui form attached fluid segment" autocomplete="false">
        <div class="two fields">
          <div class="field" :class="{ error: errors.password }">
            <label>New password</label>
            <input  placeholder="Enter your new password"
                    type="password"
                    v-model="password">
            <div v-if="errors.password" class="ui basic red pointing prompt label transition visible">{{errors.password[0]}}</div>
          </div>

          <div class="field" :class="{ error: !password_match }">
            <label>New password confirmation</label>
            <input  placeholder="Enter your new password"
                    type="password"
                    v-model="password_confirmation">
            <div v-if="!password_match" class="ui basic red pointing prompt label transition visible">does not match password</div>
          </div>
        </div>
        <button class="ui blue submit button" :class="{disabled: state.processing || !password_match || !password_same_length}" @click.prevent="changePassword()">Change my password</button>
      </form>

      <div class="ui bottom attached warning message">
        <i class="icon warning"></i>
        Do not give your passwords to other people!
      </div>
    </template>

  </div>
</template>

<script>
import store from '../../store'
import {url_for} from '../../constants'
import auth from '../../auth'

export default {
  name: 'forgotten-password',

  data () {
    return {
      state: store.state,
      email: '',
      password: '',
      password_confirmation: '',
      errors: '',
      profile: ''
    }
  },

  computed: {
    password_match: function () {
      if (this.password.length > this.password_confirmation.length) return true // dont trigger if confirm not long enough
      return this.password === this.password_confirmation
    },

    password_same_length: function () {
      return this.password.length === this.password_confirmation.length
    }
  },

  created: function () {
    if (this.$route.params.token) {this.getUser()} // load user if token is set
  },

  methods: {

    sendEmail () {
      this.$api.post(url_for('reset-password'), {email: this.email}).then(
        (response) => {
          this.state.message = { header: 'Request successful', class: 'success', list: ['Please check your email'] }
        } // no error callback - we dont reveal non existent emails
      )
    },

    getUser () {
      this.$api.get(url_for('reset-password') + '/' + this.$route.params.token).then(
        (response) => {
          this.profile = response.data
        },
        (response) => {
          this.$router.push('/login')
          this.state.message = { header: 'Invalid token', class: 'error', list: [''] }
        }
      )
    },

    changePassword () {
      this.$api.post(url_for('reset-password') + '/' + this.$route.params.token, {password: this.password}).then(
        (response) => {
          auth.storeLoginResponse(this, response.data)
          this.state.message = { header: 'Success', class: 'success', list: ['Your password is updated'] }
          this.$router.push('/authorize') // otp
        },
        (response) => {this.errors = response.data}
      )
    }
  }

}
</script>
