<template>
  <div>
    <div class="ui attached message">
      <img class="ui small right floated image" src="/static/logo.png" alt="logo">
      <div class="header">
        Log in
      </div>
      <p>Fill in your credentials to log in</p>
    </div>

    <form class="ui form attached fluid segment" autocomplete="false">
      <div class="field">
        <label>Email</label>
        <input  type="text"
                name="email"
                placeholder="Enter your email"
                v-model="credentials.email">
      </div>
      <div class="field">
        <label>Password</label>
        <input  type="password"
                name="password"
                placeholder="Enter your password"
                v-model="credentials.password">
      </div>
      <button class="ui blue submit button" :class="{disabled: state.processing}" @click.prevent="submit()">Log in</button>
    </form>

    <div class="ui bottom attached warning message">
      <i class="icon help"></i>
      No account? <router-link to="/signup">Sign up here</router-link> instead. Click <router-link to="/forgotten-password"> here</router-link> if you forgot your password.
    </div>

  </div>
</template>

<script>
import auth from '../../auth'
import store from '../../store'

export default {
  name: 'login',

  data () {
    return {
      state: store.state,
      credentials: {
        email: '',
        password: ''
      }
    }
  },

  methods: {

    submit () {
      var credentials = {
        email: this.credentials.email,
        password: this.credentials.password
      }
      auth.login(this, credentials)
    }
  }
}
</script>
