// vue app
import Vue from 'vue'
import App from './components/app.vue'

// public
import Login from './components/public/login.vue'
import ActivateUser from './components/public/activate_user.vue'
import ForgottenPassword from './components/public/forgotten_password.vue'

import Signup from './components/public/signup.vue'
import Page from './components/public/page.vue'

// user
import AuthorizeLogin from './components/authorize_login.vue'
import Profile from './components/profile/profile.vue'
import Messages from './components/messages/messages.vue'

// accounts
import Accounts from './components/accounts/accounts.vue'
import Account from './components/accounts/account.vue'

// transactions
import Transactions from './components/transactions/transactions.vue'

// other
import auth from './auth'
import store from './store'

// plugins
import VueRouter from 'vue-router'
// import VueResource from 'vue-resource' // TODO: STEP 6 - migrate to axios
Vue.use(VueRouter)
// Vue.use(VueResource) // TODO: STEP 6 - migrate to axios

// libs
import _ from 'underscore'
import NProgress from 'NProgress'
import jQuery from 'jquery'

import 'velocity-animate'

// import '../semantic/dist/semantic.min.js' // semantic is loaded via index.html

import flatpickr from 'flatpickr'
flatpickr.init.prototype.defaultConfig.prevArrow = "<i class='icon angle left'></i>"
flatpickr.init.prototype.defaultConfig.nextArrow = "<i class='icon angle right'></i>"

// libs folder
import './libs/jquery.maskMoney.js'
import './libs/printThis.js'
jQuery.fn.printThis.defaults.importStyle = '.button {display: none}'

// axios API setup
import api, { setRouter as setApiRouter } from './api'

// Make API available in all components as this.$api
Vue.prototype.$api = api

// filters
Vue.filter('displayDate', function (value) {
  return store.utils.timeStamp(value)
})

Vue.filter('humanize', function (value) {
  return store.utils.humanize(value)
})

Vue.filter('titleize', function (value, chr) {
  return store.utils.titleize(value, chr)
})

Vue.filter('modulize', function (value) {
  return store.utils.modulize(value)
})

Vue.filter('capitalize', function (value) {
  if (!value) return ''
  value = value.toString()
  return value.charAt(0).toUpperCase() + value.slice(1)
})

Vue.filter('currency', function (value, symbol) {
  if (value === null || value === undefined) return ''
  const num = parseFloat(value)
  if (isNaN(num)) return value
  const formatted = num.toFixed(2).replace(/\d(?=(\d{3})+\.)/g, '$&,')
  // symbol parameter is often empty string '' in templates
  return symbol && symbol.trim() ? symbol + formatted : formatted
})

// router configuration (Vue Router 3.x)
const router = new VueRouter({
  mode: 'hash', // Using hash mode for compatibility
  routes: [
    // public routes
    {
      path: '/',
      component: Login
    },
    {
      path: '/login',
      component: Login
    },
    {
      path: '/signup',
      component: Signup
    },
    {
      path: '/activate/:token',
      component: ActivateUser
    },
    {
      path: '/forgotten-password',
      component: ForgottenPassword,
      children: [
        {
          path: ':token',
          component: ForgottenPassword
        }
      ]
    },

    // private routes
    {
      path: '/authorize',
      name: 'authorize',
      component: AuthorizeLogin
    },
    {
      path: '/home',
      name: 'home',
      component: Account
    },

    // user
    {
      path: '/profile',
      name: 'profile',
      component: Profile
    },
    {
      path: '/messages/:page',
      name: 'messages',
      component: Messages
    },

    // accounts
    {
      path: '/accounts',
      component: Accounts
    },

    // transactions
    {
      path: '/transactions/:page',
      name: 'transactions',
      component: Transactions
    },

    // pages
    {
      path: '/about',
      name: 'about',
      component: Page
    },
    {
      path: '/terms',
      name: 'terms',
      component: Page
    },

    // redirect to root for unknown routes
    {
      path: '*',
      redirect: '/'
    }
  ]
})

// route guards (Vue Router 3.x syntax)
router.beforeEach((to, from, next) => {
  // reset transient data
  store.state.show_otp = false
  store.state.id = false
  store.state.action = false
  store.state.sub_id = false
  store.state.sub_action = false

  const publicPaths = ['/', '/login', '/signup', '/about', '/terms']

  // disable public part if authenticated
  if (!publicPaths.includes(to.path)) {
    // pass here - token is appended on these routes
    if (to.path.startsWith('/activate') || to.path.startsWith('/forgotten-password')) {
      next()
      return
    }

    // pass if logged in
    if (store.state.authenticated) {
      store.utils.scrollToTop()
      next()
    } else {
      next('/login')
    }
  } else {
    // pass for public
    next()
  }
})

// Set router reference for API interceptors
setApiRouter(router)

// start app (Vue Router 3.x + Vue 2.x syntax)
new Vue({
  router,
  render: h => h(App)
}).$mount('#app')

// export router for use in non component files
export { router }
