<template>

  <div class="ui right floated pagination menu">

    <template v-if="current_page == 1">
      <router-link class="icon item disabled" :to="{ name: route, params: { page: 1}}">
        <i class="left chevron icon"></i>
      </router-link>
    </template>
    <template v-else>
      <router-link class="icon item"
          :to="{ name: route, params: { page: current_page - 1}}"
          @click="current_page = current_page">
        <i class="left chevron icon"></i>
      </router-link>
    </template>

    <template v-if="total_pages > gap_threshold">
      <template v-for="(page, index) in gap_threshold">
        <router-link :key="index" class="item"
            :to="{ name: route, params: { page: page + 1}}"
            @click="current_page = page + 1">
          {{page + 1}}
        </router-link>
      </template>
      <div class="disabled item">
         ...
       </div>
       <template v-for="(page, index) in gap_threshold">
         <router-link :key="index + gap_threshold" class="item"
             :to="{ name: route, params: { page: page + 1 + total_pages - gap_threshold}}"
             @click="current_page = page + 1 + total_pages - gap_threshold">
           {{page + 1 + total_pages - gap_threshold}}
         </router-link>
       </template>
    </template>
    <template v-else>
      <template v-for="(page, index) in total_pages">
        <router-link :key="index" class="item"
            :to="{ name: route, params: { page: page + 1}}"
            @click="current_page = page + 1">
          {{page + 1}}
        </router-link>
      </template>
    </template>

    <template v-if="current_page == total_pages">
      <router-link class="icon item disabled" :to="{ name: route, params: { page: total_pages}}">
        <i class="right chevron icon"></i>
      </router-link>
    </template>
    <template v-else>
      <router-link class="icon item"
           :to="{ name: route, params: { page: current_page + 1}}"
           @click="current_page = current_page">
         <i class="right chevron icon"></i>
       </router-link>
    </template>

  </div>
</template>

<script>

export default {
  name: 'paginator',

  props: {'route': String, 'total_pages': Number, 'current_page': Number, 'gap_threshold': Number}

}
</script>