<template>
  <div>
    <div class="ui attached message">
      <img class="ui small right floated image" src="/static/logo.png" alt="logo">
      <div class="header">
        Sign up
      </div>
      <p>Fill out the form below to sign up for a new account</p>
    </div>

      <form novalidate class="ui form attached fluid segment" autocomplete="false">

        <h3 class="ui dividing header">Profile</h3>

        <div class="field" :class="{ error: errors.title }">
          <div class="inline fields">
            <label>Title:</label>

            <div class="field">
             <div class="ui radio checkbox" @click="profile.title = 'mr'">
               <input type="radio" name="title" value="mr"
                      tabindex="0"
                      :checked="profile.title === 'mr'">
               <label>Mr.</label>
             </div>
            </div>

            <div class="field">
             <div class="ui radio checkbox" @click="profile.title = 'ms'">
               <input type="radio" name="title" value="ms"
                      tabindex="0"
                      :checked="profile.title === 'ms'">
               <label>Ms.</label>
             </div>
            </div>

            <div v-if="errors.title" class="ui basic red left pointing prompt label transition visible">{{errors.title[0]}}</div>
          </div>
        </div>

        <div class="two fields">
          <div class="field" :class="{ error: errors.first_name }">
            <label>First name</label>
            <input  placeholder="Enter your first name"
                    type="text"
                    v-model="profile.first_name">
            <div v-if="errors.first_name" class="ui basic red pointing prompt label transition visible">
              {{errors.first_name[0]}}
            </div>
          </div>

          <div class="field" :class="{ error: errors.last_name }">
            <label>Last name</label>
            <input  placeholder="Enter your last name"
                    type="text"
                    v-model="profile.last_name">
            <div v-if="errors.last_name" class="ui basic red pointing prompt label transition visible">
              {{errors.last_name[0]}}
            </div>
          </div>
        </div>

        <div class="two fields">
          <div class="field" :class="{ error: errors.address }">
            <label>Address</label>
            <input  placeholder="Enter your address"
                    type="text"
                    v-model="profile.address">
            <div v-if="errors.address" class="ui basic red pointing prompt label transition visible">{{errors.address[0]}}</div>
          </div>

          <div class="field" :class="{ error: errors.city }">
            <label>City</label>
            <input  placeholder="Enter your city"
                    type="text"
                    v-model="profile.city">
            <div v-if="errors.city" class="ui basic red pointing prompt label transition visible">{{errors.city[0]}}</div>
          </div>
        </div>

        <div class="two fields">
          <div class="field" :class="{ error: errors.country }">
            <label>Country</label>
            <select class="ui search dropdown" v-model="profile.country" autocomplete="false">
              <option value="">Select Country</option>
              <option v-for="(country, key) in countries" :value="key" :key="key">
                {{ country[0] }}
              </option>
            </select>
            <div v-if="errors.country" class="ui basic red pointing prompt label transition visible">{{errors.country[0]}}</div>
          </div>

          <div class="field" :class="{ error: errors.zip }">
            <label>Zip code</label>
            <input  placeholder="Enter your zip code (optional)"
                    type="text"
                    v-model="profile.zip">
            <div v-if="errors.zip" class="ui basic red pointing prompt label transition visible">{{errors.zip[0]}}</div>
          </div>
        </div>

        <div class="fields">
          <div class="eight wide field" :class="{ error: errors.birth_date }">
            <label>Birth date</label>
            <div class="three fields">
              <div class="field">
                <select v-model="birth_date.year" class="ui fluid search dropdown">
                  <option value="">Year</option>
                  <option v-for="y in years" :value="y" :key="y">{{y}}</option>
                </select>
                <div v-if="errors.birth_date" class="ui basic red pointing prompt label transition visible">{{errors.birth_date[0]}}</div>
              </div>
              <div class="field">
                <select v-model="birth_date.month" class="ui fluid search dropdown">
                  <option value="">Month</option>
                  <option v-for="(m, key) in months" :value="key" :key="key">{{m}}</option>
                </select>
              </div>
              <div class="field">
                <select v-model="birth_date.day" class="ui fluid search dropdown">
                  <option value="">Day</option>
                  <option v-for="d in 31" :value="d + 1" :key="d">{{d + 1}}</option>
                </select>
              </div>
            </div>
          </div>

          <div class="eight wide field" :class="{ error: errors.phone }">
            <label>Mobile phone number</label>
            <div class="ui left labeled input">
              <div class="ui basic label">
                +{{phone_prefix}}
              </div>
              <input type="text" placeholder="Enter your mobile phone number" v-model="partial_phone">
            </div>
            <div v-if="errors.phone" class="ui basic red pointing prompt label transition visible">{{errors.phone[0]}}</div>
          </div>
        </div>

        <h3 class="ui dividing header">Account settings</h3>

        <div class="two fields">
          <div class="field" :class="{ error: errors.password }">
            <label>Password</label>
            <input  placeholder="Enter your password"
                    type="password"
                    v-model="profile.password">
            <div v-if="errors.password" class="ui basic red pointing prompt label transition visible">{{errors.password[0]}}</div>
          </div>

          <div class="field" :class="{ error: !password_match }">
            <label>Password confirmation</label>
            <input  placeholder="Enter your password"
                    type="password"
                    v-model="password_confirmation">
            <div v-if="!password_match" class="ui basic red pointing prompt label transition visible">does not match password</div>
          </div>
        </div>

        <div class="two fields">
          <div class="field" :class="{ error: errors.email }">
            <label>Email</label>
            <input  placeholder="Enter your email"
                    type="text"
                    v-model="profile.email">
            <div v-if="errors.email" class="ui basic red pointing prompt label transition visible">{{errors.email[0]}}</div>
          </div>

          <div class="field" :class="{ error: !answer_is_valid }">
            <label>Are you a human?</label>
            <input  :placeholder="`Calculate ${num1} + ${num2}`"
                    type="text"
                    v-model="answer">
          </div>
        </div>

        <div class="terms">
          <div class="ui segment" v-show="show_terms">
            <page :slug="'terms'"></page>
            <div class="ui divider hidden"></div>
            <div class="ui basic button" @click="show_terms = !show_terms">Close</div>
          </div>

          <div class="inline field" :class="{ error: errors.terms }">
            <div class="ui checkbox">
              <input  type="checkbox"
                      v-model="profile.terms"
                      v-bind:true-value="true"
                      v-bind:false-value="false">
              <label @click.prevent="openTerms()">
                I agree to the
                <a>terms and conditions</a>
              </label>
            </div>
            <div v-if="errors.terms" class="ui basic red pointing prompt label transition visible">{{errors.terms[0]}}</div>
          </div>
        </div>

        <br>
        <button class="ui blue submit button"
                @click.prevent="submit()"
                v-show="!show_terms"
                :class="{disabled: state.processing}">
          Sign up
        </button>

      </form>

    <div class="ui bottom attached warning message">
      <i class="icon help"></i>
      Already signed up? <router-link to="/login">Log in here</router-link> instead.
    </div>

  </div>
</template>

<script>
import auth from '../../auth'
import {countries, years, months, default_country} from '../../constants'
import Page from './page'
import store from '../../store'

export default {
  name: 'signup',

  data () {
    return {

      state: store.state,
      utils: store.utils,

      // profile send to server
      profile: {
        terms: false,
        country: default_country,
        password: '',
        zip: ''
      },

      // errors returned from server
      errors: '',

      // password confirmation
      password_confirmation: '',

      // countries
      countries: '',

      // phone
      phone: '',
      partial_phone: '',
      phone_prefix: countries[default_country][1],

      // birth date
      birth_date: {},

      // anti spam question
      num1: '',
      num2: '',
      answer: '',
      answer_is_valid: true,

      // terms
      show_terms: false
    }
  },

  components: {
    page: Page
  },

  // init equation
  created: function () {
    this.num1 = Math.ceil(Math.random() * 10)
    this.num2 = Math.ceil(Math.random() * 10)
    this.countries = countries
    this.years = years
    this.months = months
  },

  mounted: function () {
    try {
      if ($ && $.fn && $.fn.dropdown) {
        $('select.dropdown').dropdown()
      }
      if ($ && $.fn && $.fn.checkbox) {
        $('.ui.checkbox').checkbox()
      }
    } catch (e) {
      // Semantic UI not loaded yet
    }
  },

  watch: {
    'profile.country': function () {
      this.phone_prefix = this.countries[this.profile.country][1]
    },

    phone: function () {
      this.profile.phone = this.phone
    },

    birth_date: function () {
      this.profile.birth_date = this.birth_date.year + '-' + this.birth_date.month + '-' + this.birth_date.day
    }
  },

  computed: {
    password_match: function () {
      if (this.profile.password.length > this.password_confirmation.length) return true // dont trigger if confirm not long enough
      return this.profile.password === this.password_confirmation
    },

    password_same_length: function () {
      return this.profile.password.length === this.password_confirmation.length
    },

    phone: function () {
      return this.phone_prefix + this.partial_phone
    }
  },

  methods: {

    submit () {
      // anti spam
      if (parseInt(this.answer, 10) !== this.num1 + this.num2) {
        this.answer_is_valid = false
        return
      } else {
        this.answer_is_valid = true
      }

      // return if passwords are not same lenght
      if (!this.password_same_length) return

      // return unless passwords match
      if (!this.password_match) return

      // send to server
      auth.signup(this, this.profile)
    },

    openTerms () {
      this.show_terms = !this.show_terms
      $('.terms').velocity('scroll', { offset: '-10px', duration: 100, mobileHA: false })
    }
  }
}
</script>
